// Banque ATPL — programme théorique du pilote de ligne (EASA), du niveau débutant au niveau examen
// 010, 050 et 081 suivent l'ordre des manuels Oxford ATPL de Badis ; les autres matières suivent le programme officiel.
// Questions et explications rédigées pour l'entraînement (aucun texte des manuels n'est recopié).
// d = niveau : 1 = vocabulaire et bases, 2 = comprendre, 3 = détails, 4 = niveau examen
(function () {
const THEMES = {
  law: "010 Droit aérien",
  sys: "021 Cellule, systèmes, moteurs",
  instr: "022 Instruments",
  mb: "031 Masse et centrage",
  perf: "032 Performances",
  fp: "033 Préparation du vol",
  hp: "040 Facteurs humains",
  met: "050 Météorologie",
  nav: "061 Navigation générale",
  rnav: "062 Radionavigation",
  ops: "070 Procédures opérationnelles",
  pof: "081 Principes du vol",
  com: "090 Communications"
};
const QUESTIONS = [
// =================== 010 DROIT AÉRIEN ===================
{d:1,th:"law",q:"Que signifie le sigle ATPL ?",a:"Airline Transport Pilot Licence : la licence de pilote de ligne",w:["Air Traffic Procedure Level : un niveau de contrôle aérien","Advanced Technical Pilot Logbook : un carnet de vol","Aircraft Type Performance Limit : une limite de l'avion"],e:"C'est la licence la plus haute : elle permet d'être commandant de bord dans une compagnie aérienne. Le « théorique ATPL » regroupe 13 matières, de 010 à 090."},
{d:1,th:"law",q:"Que signifie l'OACI (ICAO en anglais) ?",a:"L'Organisation de l'aviation civile internationale, agence de l'ONU qui fixe les normes mondiales",w:["L'Office d'aviation civile irlandais","Un constructeur d'avions","La compagnie aérienne de l'ONU"],e:"ICAO = International Civil Aviation Organization, siège à Montréal. Ses règles (les Annexes) sont la base de tout le droit aérien."},
{d:1,th:"law",q:"Quel traité de 1944 a fondé l'aviation civile internationale moderne ?",a:"La convention de Chicago",w:["La convention de Varsovie","Le traité de Rome","La convention de Genève"],e:"Elle a créé l'OACI et pose le principe que chaque État est souverain sur l'espace aérien au-dessus de son territoire."},
{d:1,th:"law",q:"Que signifient VFR et IFR ?",a:"Vol à vue (Visual Flight Rules) et vol aux instruments (Instrument Flight Rules)",w:["Vol rapide et vol lent","Vol de jour et vol de nuit","Vol national et vol international"],e:"En VFR, le pilote doit voir l'extérieur et rester hors des nuages. En IFR, il peut voler dans les nuages en suivant ses instruments et le contrôle. Les avions de ligne volent en IFR."},
{d:1,th:"law",q:"Que signifie « VMC » ?",a:"Conditions météo de vol à vue (Visual Meteorological Conditions)",w:["Vitesse maximale de croisière","Vol en mode commandé","Visibilité minimale en cabine"],e:"VMC = la météo permet le vol à vue (visibilité et distance aux nuages suffisantes). L'inverse : IMC (Instrument Meteorological Conditions)."},
{d:2,th:"law",q:"Quel code transpondeur un pilote affiche-t-il en cas de panne radio ?",a:"7600",w:["7500","7700","2000"],e:"7500 = intervention illicite (détournement), 7600 = panne radio (radio failure), 7700 = urgence. Moyen mnémotechnique : 75 « taken alive », 76 « radio fix », 77 « go to heaven »."},
{d:2,th:"law",q:"Que signale le code transpondeur 7500 ?",a:"Une intervention illicite à bord (détournement)",w:["Une panne radio","Une urgence médicale","Un vol d'essai"],e:"Le contrôle comprend sans que les pirates l'entendent à la radio. Le pilote peut aussi utiliser 7700 s'il juge la situation plus adaptée."},
{d:2,th:"law",q:"Quel est le principe de la « première liberté de l'air » ?",a:"Le droit de survoler un pays étranger sans y atterrir",w:["Le droit de transporter des passagers dans un autre pays","Le droit d'atterrir pour faire le plein","Le droit de vol à l'intérieur d'un autre pays"],e:"2e liberté : escale technique (carburant, réparation) sans embarquer de passagers. Les libertés suivantes concernent le transport commercial."},
{d:2,th:"law",q:"Que signifie l'« altitude de transition » ?",a:"L'altitude à partir de laquelle on passe du calage QNH au calage standard 1013,25 hPa en montée",w:["L'altitude maximale de l'avion","L'altitude où l'on rentre le train","L'altitude de croisière"],e:"Au-dessus, on vole en « niveaux de vol » (FL). En descente, on repasse au QNH au « niveau de transition » (transition level)."},
{d:2,th:"law",q:"Que veut dire « FL 350 » ?",a:"Niveau de vol 350 : environ 35 000 ft avec le calage standard 1013,25 hPa",w:["350 km/h","Une altitude de 350 m","Le vol numéro 350"],e:"Tous les avions au-dessus de l'altitude de transition utilisent le même calage, donc ils sont séparés correctement même si la pression réelle varie."},
{d:2,th:"law",q:"Dans quel sens tourne-t-on dans un circuit d'attente standard ?",a:"Vers la droite",w:["Vers la gauche","Au choix du pilote","Dans le sens indiqué par le vent"],e:"Le circuit d'attente (holding) standard se fait en virages à droite, sauf si la carte indique un circuit à gauche (non standard)."},
{d:2,th:"law",q:"Quelle est la classe d'espace aérien la plus contrôlée, où seuls les vols IFR sont admis ?",a:"La classe A",w:["La classe G","La classe D","La classe E"],e:"Les classes vont de A (tout contrôlé, IFR seulement) à G (non contrôlé). C'est souvent la classe des espaces supérieurs où volent les avions de ligne."},
{d:3,th:"law",q:"Quel est l'âge minimum pour obtenir une licence ATPL ?",a:"21 ans",w:["18 ans","25 ans","17 ans"],e:"CPL (pilote professionnel) : 18 ans. PPL (pilote privé) : 17 ans. ATPL avion : 21 ans, avec 1 500 heures de vol."},
{d:3,th:"law",q:"En VFR dans les classes B à E, au-dessus de FL 100, quelle visibilité minimale faut-il ?",a:"8 km",w:["5 km","1 500 m","10 km"],e:"Sous FL 100 : 5 km. Dans les deux cas, il faut rester à 1 500 m horizontalement et 1 000 ft verticalement des nuages."},
{d:3,th:"law",q:"En IFR, hors relief et hors phases de décollage/atterrissage, quelle hauteur minimale au-dessus de l'obstacle le plus haut faut-il respecter ?",a:"1 000 ft (300 m) dans un rayon de 8 km",w:["500 ft dans un rayon de 1 km","2 000 ft partout","3 000 ft dans un rayon de 20 km"],e:"En région montagneuse, la marge passe à 2 000 ft (600 m). Le manuel 010 détaille ces niveaux minimaux IFR."},
{d:3,th:"law",q:"Quelles conditions faut-il pour que CAVOK apparaisse dans un bulletin météo ?",a:"Visibilité ≥ 10 km, pas de nuage sous 5 000 ft (ou l'altitude minimale de secteur), pas de CB/TCU, pas de temps significatif",w:["Ciel totalement dégagé uniquement","Vent nul et visibilité ≥ 5 km","Température positive et pas de pluie"],e:"CAVOK = « Ceiling And Visibility OK ». Il peut y avoir des nuages au-dessus de 5 000 ft : ce n'est pas forcément un ciel bleu."},
{d:3,th:"law",q:"Que signifie ACAS (ou TCAS) ?",a:"Un système anticollision embarqué qui donne des ordres de montée ou de descente pour éviter un autre avion",w:["Un radar météo","Un système d'atterrissage automatique","Un système de communication avec la cabine"],e:"TA = Traffic Advisory (alerte), RA = Resolution Advisory (ordre). En cas de RA, le pilote suit le TCAS, même si le contrôleur dit autre chose."},
{d:3,th:"law",q:"Que contient un NOTAM ?",a:"Une information temporaire importante pour les vols (piste fermée, balise en panne, zone interdite…)",w:["La météo de l'aéroport","Le plan de vol de l'avion","La liste des passagers"],e:"NOTAM = Notice To Airmen (aujourd'hui « Notice to Air Missions »). Les pilotes les lisent avant chaque vol ; ils sont diffusés par le service d'information aéronautique (AIS)."},
{d:3,th:"law",q:"Qu'est-ce que l'AIP ?",a:"La publication officielle d'information aéronautique d'un pays (aéroports, espaces, procédures)",w:["Un type de moteur","Le permis d'exploitation d'une compagnie","Un instrument de bord"],e:"AIP = Aeronautical Information Publication. C'est la « bible » aéronautique d'un pays, mise à jour selon un cycle fixe (AIRAC, tous les 28 jours)."},
{d:4,th:"law",q:"Dans un circuit d'attente sous FL 140, quelle est la durée standard du segment en rapprochement ?",a:"1 minute",w:["30 secondes","1 minute 30","2 minutes"],e:"Au-dessus de FL 140, c'est 1 minute 30. Les vitesses maximales en attente augmentent aussi avec l'altitude."},
{d:4,th:"law",q:"Selon l'OACI, quelle est la vitesse maximale en attente au-dessus de FL 200 ?",a:"265 kt (ou Mach 0,83)",w:["230 kt","240 kt","300 kt"],e:"Jusqu'à FL 140 : 230 kt ; de FL 140 à FL 200 : 240 kt ; au-dessus : 265 kt / Mach 0,83 (valeurs OACI vues dans le manuel 010)."},
{d:4,th:"law",q:"Lors d'une interception par un avion militaire, que signifie un balancement des ailes de l'intercepteur suivi d'un virage lent ?",a:"« Vous avez été intercepté, suivez-moi »",w:["« Vous pouvez continuer »","« Atterrissez immédiatement ici »","« Changez de fréquence »"],e:"L'avion intercepté répond en balançant les ailes et suit. Les signaux d'interception font partie du programme 010."},
{d:4,th:"law",q:"Quelle convention internationale traite des actes commis à bord des aéronefs (compétence de l'État d'immatriculation) ?",a:"La convention de Tokyo (1963)",w:["La convention de Chicago (1944)","La convention de Montréal (1999)","La convention de Rome (1952)"],e:"Tokyo : infractions à bord. La Haye (1970) : détournements. Montréal 1971 : actes contre la sécurité ; Montréal 1999 : responsabilité du transporteur envers les passagers."},

// =================== 021 CELLULE, SYSTÈMES, MOTEURS ===================
{d:1,th:"sys",q:"Qu'est-ce que l'APU d'un avion de ligne ?",a:"Un petit moteur auxiliaire, souvent dans la queue, qui fournit électricité et air au sol",w:["Le pilote automatique","Le train d'atterrissage principal","Le réservoir de secours"],e:"APU = Auxiliary Power Unit. Il permet de climatiser la cabine et de démarrer les moteurs sans équipement au sol."},
{d:1,th:"sys",q:"Que signifie « N1 » sur un moteur à réaction ?",a:"La vitesse de rotation de la soufflante et de l'étage basse pression, en pourcentage",w:["Le niveau de carburant","Le numéro du moteur","La température de sortie des gaz"],e:"N1 = basse pression (la grande soufflante), N2 = haute pression. Sur beaucoup d'avions, la poussée est réglée en N1."},
{d:2,th:"sys",q:"Pourquoi la cabine d'un avion de ligne est-elle pressurisée ?",a:"Pour que les passagers respirent normalement alors que l'air extérieur est trop pauvre en oxygène à haute altitude",w:["Pour rendre l'avion plus léger","Pour réduire le bruit des moteurs uniquement","Pour éviter le givrage"],e:"La pression cabine est réglée par une vanne de sortie d'air (outflow valve) qui laisse plus ou moins échapper l'air envoyé par les moteurs."},
{d:2,th:"sys",q:"D'où vient généralement l'air qui pressurise la cabine d'un avion de ligne à réaction ?",a:"De l'air prélevé sur les compresseurs des moteurs (air de prélèvement, bleed air)",w:["De bouteilles d'air comprimé","De l'extérieur sans compression","Des toilettes"],e:"Exception : le Boeing 787 utilise des compresseurs électriques dédiés plutôt que le bleed air."},
{d:2,th:"sys",q:"Que mesure l'EGT d'un moteur ?",a:"La température des gaz d'échappement",w:["L'efficacité globale de la turbine","La pression d'huile","La vitesse de l'air à l'entrée"],e:"EGT = Exhaust Gas Temperature. C'est un indicateur clé de la santé du moteur : un dépassement peut l'endommager."},
{d:3,th:"sys",q:"Combien de circuits hydrauliques indépendants possède un Airbus A320, et comment s'appellent-ils ?",a:"Trois : vert, bleu et jaune",w:["Deux : principal et secours","Quatre : A, B, C et D","Un seul, très puissant"],e:"La redondance permet de garder les commandes de vol si un ou deux circuits tombent en panne."},
{d:3,th:"sys",q:"À quoi sert l'éolienne de secours (RAT) ?",a:"À produire de l'électricité et de la pression hydraulique si tous les moteurs s'arrêtent",w:["À refroidir les freins","À démarrer l'APU","À ventiler la cabine au sol"],e:"RAT = Ram Air Turbine : une petite hélice qui sort dans le vent relatif. Elle a sauvé plusieurs avions en panne totale de moteurs."},
{d:3,th:"sys",q:"Pourquoi les moteurs modernes ont-ils un grand taux de dilution (bypass ratio) ?",a:"Accélérer beaucoup d'air un peu est plus efficace et moins bruyant qu'accélérer peu d'air très fort",w:["Pour voler plus haut","Pour produire plus d'électricité","Pour réduire le poids du moteur"],e:"Sur un moteur moderne, environ 90 % de la poussée vient de l'air froid accéléré par la soufflante, qui contourne le cœur du moteur."},
{d:4,th:"sys",q:"Que fait un inverseur de poussée ?",a:"Il dévie le flux du moteur vers l'avant pour aider au freinage après l'atterrissage",w:["Il fait reculer l'avion au roulage en toute situation","Il augmente la poussée au décollage","Il inverse le sens de rotation du moteur"],e:"Les inverseurs sont surtout utiles sur piste mouillée ou contaminée, où les freins sont moins efficaces."},
{d:4,th:"sys",q:"Que se passe-t-il lors d'une dépressurisation rapide en altitude ?",a:"Les masques à oxygène tombent et l'équipage entame une descente d'urgence vers environ 10 000 ft",w:["L'avion continue en croisière normalement","Le pilote automatique se coupe et l'avion monte","Les portes s'ouvrent automatiquement"],e:"Les masques passagers ne fournissent de l'oxygène que pendant une durée limitée (souvent 12 à 22 minutes) : il faut descendre vite."},

// =================== 022 INSTRUMENTS ===================
{d:1,th:"instr",q:"À quoi sert un tube de Pitot ?",a:"À mesurer la pression due à la vitesse de l'avion, pour calculer sa vitesse dans l'air",w:["À mesurer la température du carburant","À indiquer le cap","À mesurer le poids de l'avion"],e:"Le Pitot capte la pression totale ; les prises statiques captent la pression de l'air immobile. La différence donne la vitesse."},
{d:1,th:"instr",q:"Que montre l'horizon artificiel (indicateur d'attitude) ?",a:"L'inclinaison et l'assiette de l'avion par rapport à l'horizon",w:["L'altitude","La vitesse verticale","La quantité de carburant"],e:"C'est l'instrument central du vol aux instruments : sans voir dehors, il dit au pilote si le nez est haut ou bas et si l'avion est incliné."},
{d:2,th:"instr",q:"Quelle est la différence entre IAS et TAS ?",a:"IAS est la vitesse lue sur l'instrument ; TAS est la vraie vitesse par rapport à l'air, plus grande en altitude",w:["Ce sont deux noms de la même vitesse","TAS est la vitesse par rapport au sol","IAS est toujours plus grande que TAS"],e:"Indicated Air Speed / True Air Speed. En altitude, l'air est moins dense : pour la même IAS, l'avion va beaucoup plus vite réellement."},
{d:2,th:"instr",q:"Si les prises statiques sont bouchées en montée, que fait l'altimètre ?",a:"Il reste bloqué sur l'altitude où elles se sont bouchées",w:["Il indique zéro","Il continue de fonctionner normalement","Il indique l'altitude maximale"],e:"L'altimètre n'utilise que la pression statique. Le variomètre indiquera aussi zéro. Une panne célèbre et piégeuse."},
{d:2,th:"instr",q:"Que sont le PFD et le ND dans un cockpit moderne ?",a:"Les écrans principaux : instruments de pilotage (PFD) et navigation (ND)",w:["Deux types de moteur","Les commandes du train","Deux fréquences radio"],e:"PFD = Primary Flight Display (attitude, vitesse, altitude). ND = Navigation Display (route, météo radar, trafic)."},
{d:3,th:"instr",q:"À quoi sert le FMS ?",a:"C'est l'ordinateur de gestion du vol : il calcule la route, les performances et guide le pilote automatique",w:["C'est le système de freinage","C'est le système de climatisation","C'est la radio de secours"],e:"FMS = Flight Management System. Les pilotes y entrent la route ; il optimise vitesse et altitude et prévoit le carburant."},
{d:3,th:"instr",q:"Que fait le GPWS (ou TAWS) ?",a:"Il alerte l'équipage si l'avion se rapproche dangereusement du relief (« TERRAIN, PULL UP »)",w:["Il détecte les autres avions","Il mesure la vitesse du vent","Il gère la pressurisation"],e:"Ground Proximity Warning System. Il a fortement réduit les accidents de « vol contrôlé vers le relief » (CFIT)."},
{d:4,th:"instr",q:"Pourquoi utilise-t-on le nombre de Mach plutôt que la vitesse indiquée en haute altitude ?",a:"Parce que la limite qui compte en haute altitude est la proximité de la vitesse du son",w:["Parce que l'anémomètre ne marche plus","Parce que c'est plus précis pour le carburant uniquement","Par tradition militaire"],e:"En montant, on vole d'abord à IAS constante, puis on passe à Mach constant : c'est le « crossover altitude »."},

// =================== 031 MASSE ET CENTRAGE ===================
{d:1,th:"mb",q:"Que signifie MTOW ?",a:"La masse maximale au décollage (Maximum Take-Off Weight)",w:["La vitesse maximale au décollage","Le nombre maximal de passagers","La masse de carburant"],e:"Au-delà, l'avion n'est pas certifié pour décoller : structure, performances et freinage sont calculés pour cette masse."},
{d:2,th:"mb",q:"Pourquoi la position du centre de gravité est-elle si importante ?",a:"Elle détermine la stabilité et la manœuvrabilité de l'avion ; hors des limites, il peut devenir incontrôlable",w:["Elle ne change que le confort","Elle sert seulement à calculer le prix du billet","Elle n'a d'effet qu'au roulage"],e:"C'est pourquoi on répartit les bagages et le fret avec soin. Un centrage trop arrière est particulièrement dangereux."},
{d:2,th:"mb",q:"Qu'est-ce que la masse sans carburant (ZFW, Zero Fuel Weight) ?",a:"La masse de l'avion chargé (passagers, fret) mais sans carburant utilisable",w:["La masse de l'avion vide","La masse du carburant seul","La masse à l'atterrissage"],e:"Elle est limitée (MZFW) car le carburant dans les ailes soulage la structure : sans carburant, les ailes supportent toute la charge du fuselage."},
{d:3,th:"mb",q:"Un centrage AVANT (centre de gravité vers l'avant) rend l'avion :",a:"Plus stable mais plus lourd à manœuvrer, avec une vitesse de décrochage un peu plus élevée",w:["Plus instable et plus maniable","Plus rapide et plus économe","Impossible à faire décoller"],e:"Avec un centrage avant, l'empennage doit déporter davantage vers le bas : plus de traînée et de consommation."},
{d:3,th:"mb",q:"Comment exprime-t-on souvent la position du centre de gravité sur un avion de ligne ?",a:"En pourcentage de la corde aérodynamique moyenne (% MAC)",w:["En mètres depuis la queue","En kilogrammes","En degrés"],e:"MAC = Mean Aerodynamic Chord. Par exemple « CG à 28 % MAC »."},
{d:4,th:"mb",q:"Que signifie DOM (Dry Operating Mass) ?",a:"La masse de l'avion prêt à opérer avec équipage et équipements, mais sans charge payante ni carburant utilisable",w:["La masse maximale autorisée","La masse du fret","La masse à vide constructeur"],e:"DOM + charge payante = ZFM. ZFM + carburant = masse au décollage."},

// =================== 032 PERFORMANCES ===================
{d:1,th:"perf",q:"Que signifie V1 au décollage ?",a:"La vitesse de décision : au-delà, on continue le décollage même en cas de panne moteur",w:["La vitesse de rotation","La vitesse maximale","La vitesse de sécurité au décollage"],e:"Avant V1, on peut s'arrêter sur la piste restante. Après V1, on n'a plus assez de piste pour s'arrêter : on décolle."},
{d:1,th:"perf",q:"Que signifie VR ?",a:"La vitesse à laquelle le pilote tire sur le manche pour lever le nez (rotation)",w:["La vitesse de retour","La vitesse de référence en approche","La vitesse maximale avec volets"],e:"L'ordre classique : V1 (décision), VR (rotation), V2 (vitesse de sécurité au décollage, à atteindre à 35 ft)."},
{d:2,th:"perf",q:"Pourquoi un aéroport chaud et en altitude rallonge-t-il la distance de décollage ?",a:"L'air y est moins dense : les ailes portent moins et les moteurs poussent moins",w:["La piste y est plus glissante","Les passagers sont plus lourds","La gravité y est plus forte"],e:"C'est la notion d'« altitude densité ». Les avions décollent parfois avec moins de passagers ou de carburant à Mexico ou La Paz."},
{d:2,th:"perf",q:"Pourquoi décolle-t-on face au vent ?",a:"Pour atteindre la vitesse de vol avec moins de vitesse au sol, donc moins de piste",w:["Pour consommer moins en croisière","Pour réduire le bruit","Par habitude uniquement"],e:"Un vent arrière augmente fortement la distance de décollage et d'atterrissage : il est strictement limité."},
{d:3,th:"perf",q:"Que signifient TORA et ASDA ?",a:"La longueur de piste disponible pour le roulage au décollage, et la distance disponible pour accélérer puis s'arrêter",w:["Deux types de piste en herbe","La distance d'atterrissage et la distance de roulage","Deux codes de balisage lumineux"],e:"TORA = Take-Off Run Available, ASDA = Accelerate-Stop Distance Available, TODA = Take-Off Distance Available (avec prolongement dégagé)."},
{d:3,th:"perf",q:"Pourquoi les performances d'un bimoteur sont-elles calculées avec un moteur en panne ?",a:"La réglementation exige qu'il puisse toujours décoller et monter en sécurité si un moteur tombe en panne au pire moment",w:["Pour économiser un moteur","Parce que les deux moteurs ne fonctionnent jamais ensemble","Pour calculer le prix du vol"],e:"C'est la logique « OEI » (One Engine Inoperative) : une pente de montée minimale doit être garantie même avec un seul moteur."},
{d:4,th:"perf",q:"Pourquoi une piste contaminée (neige, eau stagnante) peut-elle aussi allonger la distance d'ACCÉLÉRATION ?",a:"La neige ou l'eau freinent les roues et créent une traînée supplémentaire",w:["Elle réduit la poussée des moteurs","Elle n'a aucun effet sur l'accélération","Elle alourdit l'avion"],e:"Et à l'atterrissage, l'aquaplanage réduit le freinage. Les calculs de performance utilisent des coefficients spécifiques pour chaque contaminant."},

// =================== 033 PRÉPARATION DU VOL ===================
{d:1,th:"fp",q:"Qu'est-ce que le « trip fuel » ?",a:"Le carburant nécessaire pour aller du départ à la destination",w:["Le carburant de réserve finale","Le carburant pour le roulage","Le carburant pour l'aéroport de dégagement"],e:"On y ajoute : roulage, réserve de route (contingency), carburant de dégagement, réserve finale, et éventuellement du supplément."},
{d:2,th:"fp",q:"Qu'est-ce qu'un aéroport de dégagement (alternate) ?",a:"Un aéroport où l'avion peut aller s'il ne peut pas se poser à destination",w:["L'aéroport de départ","Un aéroport réservé aux militaires","L'aéroport où l'équipage dort"],e:"On emporte toujours assez de carburant pour rejoindre le dégagement, puis encore une réserve."},
{d:3,th:"fp",q:"Pour un avion à réaction, à quoi correspond la réserve finale de carburant ?",a:"Environ 30 minutes d'attente à 1 500 ft au-dessus du terrain",w:["2 heures de vol supplémentaires","10 % du carburant total","Le carburant pour refaire le vol aller"],e:"C'est le minimum absolu. Si l'équipage prévoit d'atterrir en dessous, il déclare une urgence carburant (« MAYDAY FUEL »)."},
{d:3,th:"fp",q:"Pourquoi la route la plus courte entre Paris et New York passe-t-elle près de l'Irlande et de Terre-Neuve plutôt que plein ouest sur la carte ?",a:"Sur une sphère, le chemin le plus court est un arc de grand cercle, qui paraît courbé sur une carte plate",w:["Pour éviter les tempêtes uniquement","Pour survoler des aéroports","Parce que les avions doivent suivre les côtes"],e:"On ajuste ensuite selon les vents (jet stream) : les routes transatlantiques changent chaque jour."},
{d:4,th:"fp",q:"Que signifie ETOPS ?",a:"Des règles qui autorisent les bimoteurs à voler loin de tout aéroport de dégagement (par exemple au-dessus des océans)",w:["Un système de pilotage automatique","Une norme de bruit","Un type de carburant"],e:"Par exemple « ETOPS 180 » : l'avion peut être à 180 minutes de vol sur un seul moteur du dégagement le plus proche."},

// =================== 040 FACTEURS HUMAINS ===================
{d:1,th:"hp",q:"Qu'est-ce que l'hypoxie ?",a:"Un manque d'oxygène dans le corps, dangereux en altitude",w:["Une peur de l'avion","Une baisse de tension due à la fatigue","Un trouble de la vue"],e:"Elle est traîtresse : euphorie, perte de jugement, sans qu'on s'en rende compte. C'est pour ça qu'on teste les pilotes en caisson."},
{d:2,th:"hp",q:"Que signifie le « temps de conscience utile » (TUC) ?",a:"Le temps pendant lequel on peut encore agir efficacement après une perte d'oxygène",w:["La durée maximale de service","Le temps de sommeil nécessaire","Le temps de réaction moyen"],e:"Il diminue fortement avec l'altitude : quelques minutes vers 25 000 ft, et seulement quelques dizaines de secondes vers 35 000-40 000 ft. D'où les masques en premier."},
{d:2,th:"hp",q:"Qu'est-ce que le CRM ?",a:"La gestion des ressources de l'équipage : communication, travail d'équipe, prise de décision",w:["Le calcul de route manuel","Une check-list moteur","Le contrôle radar militaire"],e:"CRM = Crew Resource Management. Né après des accidents où un copilote n'osait pas contredire le commandant."},
{d:3,th:"hp",q:"Qu'est-ce que l'illusion somatogravique ?",a:"Lors d'une forte accélération sans repères visuels, le pilote a l'impression de cabrer et risque de piquer",w:["La sensation de tourner après un virage prolongé","Un mal de l'air","Une illusion d'optique sur la piste"],e:"L'oreille interne confond accélération et inclinaison. Danger classique au décollage de nuit : la solution est de croire ses instruments."},
{d:3,th:"hp",q:"Que représente le « modèle du fromage suisse » de James Reason ?",a:"Un accident survient quand les failles de plusieurs barrières de sécurité s'alignent",w:["La façon de couper les repas à bord","Un modèle de turbulence","Une méthode de navigation"],e:"Chaque barrière (conception, procédures, formation, équipage) a des trous ; la sécurité consiste à multiplier et renforcer les barrières."},
{d:4,th:"hp",q:"Pourquoi plonger en bouteille juste avant un vol est-il dangereux ?",a:"L'azote dissous dans le corps peut former des bulles en altitude (accident de décompression)",w:["Cela fatigue les yeux","Cela déshydrate uniquement","Ce n'est pas dangereux"],e:"Il faut attendre généralement 12 à 24 heures selon le type de plongée avant de prendre l'avion."},

// =================== 050 MÉTÉOROLOGIE ===================
{d:1,th:"met",q:"Dans quelle couche de l'atmosphère se produit presque toute la météo ?",a:"La troposphère",w:["La stratosphère","La mésosphère","La thermosphère"],e:"Elle va du sol jusqu'à la tropopause, vers 11 km en moyenne (plus haute à l'équateur, plus basse aux pôles)."},
{d:1,th:"met",q:"Qu'est-ce que le point de rosée ?",a:"La température à laquelle l'air doit refroidir pour que sa vapeur d'eau se condense",w:["La température maximale de la journée","La température du sol le matin","La température de l'eau de pluie"],e:"Quand la température rejoint le point de rosée, l'air est saturé : brouillard ou nuages se forment."},
{d:1,th:"met",q:"Que signifie METAR ?",a:"Le bulletin d'observation météo d'un aéroport, émis en général toutes les 30 ou 60 minutes",w:["Une prévision sur 24 heures","Une carte des vents en altitude","Un avertissement de cyclone"],e:"Il décrit le temps réel : vent, visibilité, nuages, température, pression. Le TAF, lui, est la prévision."},
{d:1,th:"met",q:"Que signifie l'abréviation TAF ?",a:"La prévision météo d'un aéroport (Terminal Aerodrome Forecast)",w:["L'observation météo en temps réel","Un avertissement de turbulence","Un code d'urgence"],e:"Un TAF couvre en général 9 à 30 heures et utilise les mêmes codes que le METAR, avec des groupes de changement (BECMG, TEMPO, PROB)."},
{d:1,th:"met",q:"Quel nuage est associé aux orages ?",a:"Le cumulonimbus (CB)",w:["Le cirrus","Le stratus","L'altocumulus"],e:"Le CB peut monter jusqu'à la tropopause : turbulence violente, grêle, givrage, foudre, cisaillement. Les avions de ligne le contournent."},
{d:2,th:"met",q:"Dans l'atmosphère standard (ISA), quelle est la température et la pression au niveau de la mer ?",a:"15 °C et 1013,25 hPa",w:["0 °C et 1000 hPa","20 °C et 1013,25 hPa","15 °C et 1020 hPa"],e:"L'ISA est une atmosphère « moyenne » de référence. La température y baisse d'environ 2 °C par 1 000 ft (6,5 °C par km) jusqu'à la tropopause."},
{d:2,th:"met",q:"Dans l'hémisphère Nord, dans quel sens tourne le vent autour d'une dépression ?",a:"Dans le sens inverse des aiguilles d'une montre",w:["Dans le sens des aiguilles d'une montre","Il ne tourne pas","Il va droit vers le centre"],e:"C'est l'effet de la force de Coriolis. Loi de Buys-Ballot : dos au vent dans l'hémisphère Nord, la dépression est à gauche."},
{d:2,th:"met",q:"Que signifient QNH et QFE ?",a:"QNH : calage qui fait lire l'altitude au-dessus de la mer ; QFE : calage qui fait lire la hauteur au-dessus de l'aéroport",w:["Deux fréquences radio","Deux types de nuages","La pression maximale et minimale de la journée"],e:"Ces « codes Q » viennent de la télégraphie. Le QNE correspond au calage standard 1013,25 hPa."},
{d:2,th:"met",q:"Que dit l'expression « haute vers basse, gare à la casse » (high to low, look out below) ?",a:"En volant vers une zone de basse pression sans recaler l'altimètre, on est plus bas que ce qu'indique l'instrument",w:["Il faut toujours voler vers les hautes pressions","Il faut descendre en arrivant vers une dépression","Le vent est plus fort près des anticyclones"],e:"Même logique avec la température : un air plus froid que l'ISA place aussi l'avion plus bas que prévu. Dangereux près du relief."},
{d:2,th:"met",q:"Quelle est la différence entre brume (BR) et brouillard (FG) dans un METAR ?",a:"Brouillard : visibilité inférieure à 1 000 m ; brume : entre 1 000 m et 5 000 m",w:["La brume est sèche, le brouillard est mouillé, sans lien avec la visibilité","C'est la même chose","Le brouillard n'existe qu'en hiver"],e:"BR vient du français « brume », FG de l'anglais « fog ». HZ (brume sèche, haze) est due à des particules sèches."},
{d:2,th:"met",q:"Que signifie l'abréviation « SCT 025 » dans un METAR ?",a:"Des nuages épars (3 à 4 octas) à 2 500 ft",w:["Une visibilité de 2 500 m","Un vent de 25 nœuds","Une température de 25 °C"],e:"FEW = 1-2 octas, SCT = 3-4, BKN = 5-7, OVC = 8 (ciel couvert). La hauteur est donnée en centaines de pieds."},
{d:2,th:"met",q:"Qu'est-ce qu'un jet stream ?",a:"Un courant de vent très fort et étroit en haute altitude, près de la tropopause",w:["Le souffle d'un réacteur","Un vent chaud de montagne","Un courant marin"],e:"Il peut dépasser 150 kt. Vent arrière = gain de temps et de carburant (vols vers l'est sur l'Atlantique), mais turbulence en air clair possible sur ses bords."},
{d:2,th:"met",q:"Quels sont les trois stades de vie d'un orage ?",a:"Le stade cumulus, le stade de maturité et le stade de dissipation",w:["La naissance, la pluie, la grêle","Le matin, l'après-midi, le soir","Le front chaud, le front froid, l'occlusion"],e:"Le stade de maturité est le plus dangereux : courants ascendants et descendants violents, précipitations, grêle et foudre."},
{d:3,th:"met",q:"Quel est le gradient adiabatique sec (DALR) ?",a:"Environ 3 °C par 1 000 ft (1 °C par 100 m)",w:["Environ 1,5 °C par 1 000 ft","Environ 2 °C par 1 000 ft","Environ 6 °C par 1 000 ft"],e:"Une particule d'air non saturée qui monte se refroidit à ce rythme. Saturée, elle se refroidit moins vite (SALR, environ 1,5 à 1,8 °C/1 000 ft), car la condensation libère de la chaleur."},
{d:3,th:"met",q:"Quand dit-on que l'atmosphère est instable ?",a:"Quand une particule d'air soulevée reste plus chaude que l'air autour et continue de monter",w:["Quand il y a beaucoup de vent","Quand la pression baisse","Quand il pleut"],e:"Air instable : cumulus, averses, orages, turbulence. Air stable : stratus, brouillard, visibilité réduite mais air calme."},
{d:3,th:"met",q:"Quelle est la succession typique des nuages à l'approche d'un front chaud ?",a:"Cirrus, puis cirrostratus, altostratus et enfin nimbostratus avec pluie continue",w:["Cumulonimbus puis ciel clair","Stratus puis cumulus","Altocumulus puis cirrus"],e:"L'air chaud glisse lentement au-dessus de l'air froid : les nuages s'abaissent et s'épaississent progressivement sur des centaines de kilomètres."},
{d:3,th:"met",q:"Qu'est-ce que l'effet de foehn ?",a:"Un vent chaud et sec qui descend sur le versant sous le vent d'une montagne",w:["Un brouillard de vallée","Un vent froid qui descend d'un glacier","Une tempête tropicale"],e:"L'air se refroidit lentement en montant saturé (pluie au vent), puis se réchauffe vite en descendant sec : il arrive plus chaud et plus sec de l'autre côté."},
{d:3,th:"met",q:"Quel type de givrage est le plus dangereux, transparent et lourd, formé par de grosses gouttes surfondues ?",a:"Le givre transparent (verglas, clear ice)",w:["Le givre blanc (rime ice)","La gelée blanche (hoar frost)","La neige mouillée"],e:"Les grosses gouttes s'étalent avant de geler : couche lisse, dense et difficile à voir. Surtout entre 0 et environ -10 °C, dans les cumuliformes."},
{d:3,th:"met",q:"Qu'est-ce qu'une microrafale (microburst) ?",a:"Un courant descendant très violent et localisé sous un orage, qui s'étale en touchant le sol",w:["Un petit tourbillon de poussière","Une rafale de neige","Un vent régulier de vallée"],e:"Très dangereuse à l'atterrissage : l'avion gagne d'abord de la vitesse (vent de face), puis rencontre un fort vent descendant et arrière."},
{d:3,th:"met",q:"Qu'est-ce que la zone de convergence intertropicale (ZCIT, ITCZ) ?",a:"Une bande proche de l'équateur où les alizés des deux hémisphères se rencontrent, avec de nombreux orages",w:["Une zone sans aucun vent","Une zone de haute pression aux tropiques","La limite entre air polaire et air tropical"],e:"Le vol AF447 traversait cette zone en 2009. Sa position se déplace avec les saisons."},
{d:3,th:"met",q:"Que signifie « TEMPO » dans un TAF ?",a:"Des fluctuations temporaires, de moins d'une heure à chaque fois et au total moins de la moitié de la période",w:["Un changement définitif","Une probabilité de 30 %","La température"],e:"BECMG = le changement devient permanent. PROB30 / PROB40 = probabilité d'un phénomène."},
{d:4,th:"met",q:"Dans l'ISA, à quelle altitude et quelle température se situe la tropopause ?",a:"Environ 11 km (36 090 ft), à −56,5 °C",w:["Environ 5 km, à −20 °C","Environ 20 km, à −80 °C","Environ 11 km, à 0 °C"],e:"Au-dessus, dans la basse stratosphère, la température reste constante dans le modèle ISA."},
{d:4,th:"met",q:"Pourquoi la tropopause est-elle plus haute à l'équateur qu'aux pôles ?",a:"L'air chaud près du sol à l'équateur dilate la colonne d'air et la pousse plus haut",w:["La Terre tourne plus vite aux pôles","La gravité est plus forte à l'équateur","Elle est à la même hauteur partout"],e:"Environ 16-18 km à l'équateur contre 8-9 km aux pôles. C'est aussi pourquoi les orages tropicaux montent si haut."},
{d:4,th:"met",q:"Qu'est-ce qu'une occlusion ?",a:"Un front formé quand le front froid rattrape le front chaud et soulève l'air chaud du sol",w:["Un front qui ne bouge plus","Un cyclone tropical","Un anticyclone d'hiver"],e:"C'est le stade de fin de vie d'une dépression des latitudes moyennes. Le manuel 050 lui consacre un chapitre entier."},
{d:4,th:"met",q:"Que décrit un SIGMET ?",a:"Un avertissement sur des phénomènes dangereux en route (orages, turbulence ou givrage sévères, cendres volcaniques…)",w:["La météo prévue à l'aéroport de destination","La liste des pistes fermées","La météo de l'heure passée"],e:"Les SIGMET concernent tous les avions. Les AIRMET concernent surtout les vols à basse altitude."},
{d:4,th:"met",q:"Pourquoi les cendres volcaniques sont-elles si dangereuses pour les réacteurs ?",a:"Elles fondent dans les chambres de combustion et se solidifient sur les aubes de turbine, pouvant éteindre les moteurs",w:["Elles bouchent uniquement les vitres","Elles alourdissent l'avion","Elles n'ont pas d'effet à haute altitude"],e:"En 1982, un Boeing 747 de British Airways a perdu ses 4 moteurs dans un nuage de cendres avant de les redémarrer en descente. En 2010, l'éruption islandaise a fermé l'espace aérien européen."},

// =================== 061 NAVIGATION GÉNÉRALE ===================
{d:1,th:"nav",q:"À combien de mètres correspond un mille nautique (NM) ?",a:"1 852 m",w:["1 000 m","1 609 m","2 000 m"],e:"1 NM = 1 minute d'arc de latitude. 1 nœud (kt) = 1 NM par heure. Le mile terrestre (statute mile), lui, fait 1 609 m."},
{d:1,th:"nav",q:"Quelle heure de référence utilise-t-on en aviation dans le monde entier ?",a:"L'heure UTC (temps universel coordonné), notée « Z » (Zulu)",w:["L'heure de Paris","L'heure du pays de départ","L'heure locale de chaque aéroport"],e:"Un METAR « 231020Z » signifie le 23 du mois à 10 h 20 UTC. Ça évite les erreurs de fuseau horaire."},
{d:2,th:"nav",q:"Quelle est la différence entre le Nord vrai et le Nord magnétique ?",a:"Le Nord vrai est le pôle géographique ; le Nord magnétique est la direction indiquée par la boussole",w:["Ce sont les mêmes","Le Nord magnétique est toujours exactement au pôle","Le Nord vrai change chaque année"],e:"L'écart entre les deux s'appelle la déclinaison magnétique (variation). Elle change selon le lieu et lentement avec le temps."},
{d:2,th:"nav",q:"Qu'est-ce qu'une route orthodromique (grand cercle) ?",a:"Le chemin le plus court entre deux points du globe",w:["Une route à cap constant","Une route qui suit l'équateur","Une route qui évite les montagnes"],e:"La loxodromie (rhumb line) garde un cap constant mais est plus longue. Les longs courriers suivent des routes proches du grand cercle."},
{d:3,th:"nav",q:"Qu'est-ce que la dérive en navigation ?",a:"L'angle entre le cap de l'avion et sa route réelle, causé par le vent de travers",w:["La perte d'altitude","L'erreur de l'horloge","Le changement de déclinaison"],e:"Pour suivre une route, le pilote met le nez un peu face au vent : c'est la correction de dérive."},
{d:4,th:"nav",q:"Quelle projection cartographique conserve les angles et représente une route à cap constant par une droite ?",a:"La projection de Mercator",w:["La projection de Lambert","La projection polaire stéréographique","La projection de Peters"],e:"Pratique pour la navigation à cap constant, mais elle déforme beaucoup les surfaces près des pôles (le Groenland y paraît énorme)."},

// =================== 062 RADIONAVIGATION ===================
{d:1,th:"rnav",q:"À quoi sert un VOR ?",a:"C'est une balise radio au sol qui permet de savoir dans quelle direction on se trouve par rapport à elle",w:["Un radar météo","Une radio pour parler au contrôle","Un système anticollision"],e:"Le VOR donne des « radiales » de 0 à 360°. Souvent couplé à un DME qui donne la distance."},
{d:1,th:"rnav",q:"Que fournit un ILS ?",a:"Un guidage précis vers la piste, en direction (localizer) et en pente de descente (glide slope)",w:["La météo de l'aéroport","La liste des avions au sol","L'éclairage de la piste"],e:"ILS = Instrument Landing System. Il permet d'atterrir avec une visibilité très faible, jusqu'à l'atterrissage automatique en catégorie III."},
{d:2,th:"rnav",q:"Quelle est la pente typique d'un glide slope d'ILS ?",a:"3 degrés",w:["1 degré","6 degrés","10 degrés"],e:"Règle utile : sur une pente de 3°, l'avion descend d'environ 300 ft par mille nautique. Certains aéroports (London City) ont des pentes plus fortes."},
{d:2,th:"rnav",q:"Pourquoi la distance DME est-elle une « distance oblique » ?",a:"Elle mesure la distance en ligne droite entre l'avion et la balise, en tenant compte de l'altitude",w:["Elle est mesurée en diagonale sur la carte","Elle est toujours fausse","Elle est mesurée au sol"],e:"Au-dessus de la balise, le DME n'indique pas zéro mais l'altitude de l'avion (en NM). L'écart est négligeable loin de la balise."},
{d:3,th:"rnav",q:"Que signifie RNP dans « approche RNP » ?",a:"Required Navigation Performance : une précision de navigation exigée et surveillée à bord, souvent avec le GPS",w:["Radio Navigation Primaire","Runway Not Prepared","Radar National de Proximité"],e:"Avec le RNP, on peut suivre des trajectoires courbes précises sans balise au sol, utile en montagne ou pour réduire le bruit."},
{d:4,th:"rnav",q:"Pourquoi le GPS utilisé en aviation a-t-il besoin d'une surveillance d'intégrité (RAIM) ?",a:"Pour détecter qu'un satellite donne une mauvaise information et ne pas guider l'avion avec une position fausse",w:["Pour mesurer l'altitude","Pour économiser la batterie","Pour communiquer avec la tour"],e:"Une position fausse sans alerte serait bien plus dangereuse qu'une panne visible. Le brouillage GPS est aujourd'hui un vrai problème opérationnel dans certaines régions."},

// =================== 070 PROCÉDURES OPÉRATIONNELLES ===================
{d:1,th:"ops",q:"Qu'est-ce que la MEL ?",a:"La liste minimale d'équipements : ce qui peut être en panne tout en permettant le vol, sous conditions",w:["La liste des passagers","Le menu à bord","La liste des aéroports autorisés"],e:"MEL = Minimum Equipment List. Exemple : une lampe de lecture en panne n'empêche pas de partir, un système critique oui."},
{d:2,th:"ops",q:"Pourquoi faut-il attendre derrière un gros avion qui vient de décoller ?",a:"À cause de la turbulence de sillage : deux tourbillons puissants laissés par ses ailes",w:["À cause du bruit","Pour laisser la piste refroidir","Pour des raisons administratives"],e:"Les avions sont classés par catégorie de sillage (léger, moyen, lourd, et « super » pour l'A380) avec des espacements minimaux."},
{d:3,th:"ops",q:"Que signifie le « temps de protection » (holdover time) d'un dégivrage ?",a:"La durée pendant laquelle le liquide antigivrage empêche la glace de se reformer avant le décollage",w:["La durée du dégivrage","La durée maximale d'attente en vol","Le temps de chauffe des moteurs"],e:"Si l'avion dépasse ce temps avant de décoller, il doit être retraité : une aile même légèrement givrée peut empêcher le décollage."},
{d:3,th:"ops",q:"Que fait un avion lors d'une vidange de carburant (fuel jettison) ?",a:"Il largue du carburant en vol pour réduire sa masse avant un atterrissage d'urgence",w:["Il transfère du carburant entre deux avions","Il refroidit les moteurs","Il nettoie les réservoirs"],e:"Certains avions ne peuvent pas atterrir à leur masse de décollage. Le carburant s'évapore en grande partie avant d'atteindre le sol."},
{d:4,th:"ops",q:"Qu'est-ce qu'une remise de gaz (go-around) ?",a:"Interrompre l'approche et remonter pour refaire une tentative ou se dérouter",w:["Remettre de la poussée en croisière","Faire le plein en vol","Un atterrissage raté avec dommages"],e:"C'est une manœuvre normale et sûre, à faire dès qu'une approche n'est pas stabilisée. Une approche non stabilisée maintenue est une cause majeure d'accidents."},

// =================== 081 PRINCIPES DU VOL ===================
{d:1,th:"pof",q:"Quelles sont les quatre forces qui s'exercent sur un avion en vol ?",a:"La portance, le poids, la poussée et la traînée",w:["La vitesse, l'altitude, le cap et le vent","La gravité, l'électricité, la pression et la chaleur","La portance, la vitesse, la masse et le carburant"],e:"En vol rectiligne stabilisé, portance = poids et poussée = traînée."},
{d:1,th:"pof",q:"Qu'est-ce que l'« angle d'attaque » ?",a:"L'angle entre l'aile (sa corde) et la direction de l'air qui arrive dessus (vent relatif)",w:["L'angle entre l'avion et l'horizon","L'angle de virage","L'angle de la piste"],e:"À ne pas confondre avec l'assiette (angle avec l'horizon). C'est l'angle d'attaque qui détermine la portance… et le décrochage."},
{d:1,th:"pof",q:"Que se passe-t-il lors d'un décrochage (stall) ?",a:"L'angle d'attaque est trop grand, l'air se décolle de l'aile et la portance chute brutalement",w:["Les moteurs s'arrêtent","L'avion va trop vite","Le train d'atterrissage se bloque"],e:"Un décrochage n'a rien à voir avec les moteurs. Il dépend de l'angle d'attaque : on peut décrocher à n'importe quelle vitesse."},
{d:1,th:"pof",q:"À quoi servent les volets (flaps) ?",a:"À augmenter la portance à basse vitesse, pour le décollage et l'atterrissage",w:["À faire tourner l'avion","À freiner au sol uniquement","À monter plus vite en croisière"],e:"Ils augmentent la courbure et la surface de l'aile, ce qui permet de voler plus lentement sans décrocher. En contrepartie, ils ajoutent de la traînée."},
{d:1,th:"pof",q:"Quelles gouvernes commandent le roulis, le tangage et le lacet ?",a:"Ailerons (roulis), gouverne de profondeur (tangage), gouverne de direction (lacet)",w:["Volets, becs et spoilers","Trains, freins et inverseurs","Ailerons uniquement"],e:"Roulis = inclinaison des ailes, tangage = nez haut/bas, lacet = nez à gauche/droite."},
{d:2,th:"pof",q:"Dans la formule de portance L = ½ ρ V² S CL, que se passe-t-il si la vitesse double ?",a:"La portance est multipliée par 4",w:["Elle double","Elle reste la même","Elle est divisée par 2"],e:"La portance dépend du carré de la vitesse. ρ = densité de l'air, S = surface alaire, CL = coefficient de portance (lié à l'angle d'attaque)."},
{d:2,th:"pof",q:"Comment évolue la traînée induite quand la vitesse augmente ?",a:"Elle diminue",w:["Elle augmente","Elle reste constante","Elle devient nulle à grande vitesse"],e:"La traînée induite vient de la production de portance (grand angle d'attaque à basse vitesse). La traînée parasite, elle, augmente avec la vitesse. Leur somme est minimale à la vitesse VMD."},
{d:2,th:"pof",q:"Pourquoi les ailes de planeur sont-elles très longues et fines ?",a:"Un grand allongement réduit la traînée induite et améliore la finesse",w:["Pour porter plus de carburant","Pour aller plus vite","Pour mieux résister à la foudre"],e:"Allongement (aspect ratio) = envergure² / surface. Les avions de ligne récents ont aussi des ailes de plus en plus allongées pour économiser du carburant."},
{d:2,th:"pof",q:"Qu'est-ce que l'effet de sol ?",a:"Près du sol, la traînée induite diminue : l'avion « flotte » davantage à l'arrondi",w:["L'attraction de l'avion par la piste","Les turbulences du vent au sol","La vibration du train d'atterrissage"],e:"Il apparaît à une hauteur inférieure à environ une envergure. Il peut faire décoller un avion trop tôt, qui retombe en sortant de l'effet de sol."},
{d:2,th:"pof",q:"À quoi servent les winglets ?",a:"À réduire les tourbillons en bout d'aile et donc la traînée induite",w:["À stocker des antennes uniquement","À éclairer l'aile","À augmenter le poids"],e:"Gain typique de quelques pour cent de carburant sur un long vol."},
{d:3,th:"pof",q:"En virage à 60° d'inclinaison en palier, quel est le facteur de charge ?",a:"2 (on « pèse » deux fois son poids)",w:["1","1,41","3"],e:"n = 1 / cos(inclinaison). À 45°, n ≈ 1,41 ; à 60°, n = 2. Le manuel 081 détaille ce calcul."},
{d:3,th:"pof",q:"En virage à 60° d'inclinaison, comment évolue la vitesse de décrochage ?",a:"Elle augmente d'environ 41 % (multipliée par √2)",w:["Elle reste la même","Elle double","Elle diminue"],e:"La vitesse de décrochage est proportionnelle à la racine du facteur de charge : √2 ≈ 1,41. C'est pour ça que les virages serrés à basse vitesse sont dangereux."},
{d:3,th:"pof",q:"Que font les becs de bord d'attaque (slats) ?",a:"Ils retardent le décollement de l'air et augmentent l'angle d'attaque maximal avant décrochage",w:["Ils réduisent la portance pour descendre","Ils servent de freins aérodynamiques","Ils refroidissent les moteurs"],e:"Les volets augmentent surtout la portance ; les becs permettent de voler à un angle d'attaque plus grand. Les deux ensemble réduisent beaucoup la vitesse d'approche."},
{d:3,th:"pof",q:"Que fait un centrage arrière sur la stabilité longitudinale ?",a:"Il réduit la stabilité ; trop arrière, l'avion peut devenir instable en tangage",w:["Il augmente la stabilité","Il n'a aucun effet","Il rend le décrochage impossible"],e:"Un centrage arrière rend l'avion plus maniable et un peu plus économe, mais il existe une limite à ne jamais dépasser."},
{d:3,th:"pof",q:"Pourquoi les ailes des avions de ligne sont-elles en flèche ?",a:"Pour retarder l'apparition des ondes de choc quand on vole près de Mach 1",w:["Pour être plus jolies","Pour augmenter la portance à basse vitesse","Pour faciliter le stationnement"],e:"La flèche réduit la composante de la vitesse perpendiculaire au bord d'attaque. En contrepartie, elle dégrade le comportement à basse vitesse."},
{d:3,th:"pof",q:"Qu'est-ce que le « roulis hollandais » (Dutch roll) ?",a:"Une oscillation combinée de lacet et de roulis, typique des avions à ailes en flèche",w:["Une figure de voltige","Un décrochage en virage","Une vibration du moteur"],e:"On la corrige automatiquement avec un amortisseur de lacet (yaw damper) : encore de l'automatique !"},
{d:3,th:"pof",q:"Qu'est-ce que le nombre de Mach critique (Mcrit) ?",a:"Le Mach de vol où l'air atteint pour la première fois la vitesse du son quelque part sur l'aile",w:["La vitesse maximale de l'avion","Mach 1 exactement","La vitesse de décrochage en altitude"],e:"Au-delà, des ondes de choc apparaissent : traînée qui augmente fortement, possible vibration (buffet)."},
{d:4,th:"pof",q:"Qu'est-ce que le « coffin corner » (coin du cercueil) ?",a:"L'altitude où la vitesse de décrochage et la vitesse maximale (buffet haute vitesse) se rapprochent dangereusement",w:["Un virage trop serré au roulage","Le coin arrière de la cabine","Une zone de turbulence au-dessus des montagnes"],e:"En très haute altitude, la marge entre « trop lent » et « trop rapide » devient très petite. C'est une limite de l'altitude maximale de l'avion."},
{d:4,th:"pof",q:"Qu'est-ce que VA (vitesse de manœuvre) ?",a:"La vitesse en dessous de laquelle un braquage complet d'une gouverne ne peut pas casser la structure : l'avion décroche avant",w:["La vitesse d'approche","La vitesse maximale avec le train sorti","La vitesse de croisière économique"],e:"Au-dessus de VA, un mouvement brutal des commandes peut dépasser le facteur de charge maximal. VA diminue quand la masse diminue."},
{d:4,th:"pof",q:"Que signifient VMO et MMO ?",a:"La vitesse indiquée et le nombre de Mach maximaux en exploitation",w:["Les vitesses minimales de décollage","Les vitesses de manœuvre","Les vitesses en cas de panne moteur"],e:"VMO limite en basse altitude (pression dynamique et structure), MMO en haute altitude (effets de compressibilité). Un dépassement déclenche une alarme de survitesse."},
{d:4,th:"pof",q:"Pourquoi met-on une hélice « en drapeau » quand son moteur tombe en panne ?",a:"Pour orienter ses pales dans le vent et réduire fortement la traînée",w:["Pour redémarrer le moteur","Pour freiner l'avion","Pour signaler la panne aux autres avions"],e:"Une hélice qui tourne en moulinet freine énormément l'avion. En drapeau, elle s'arrête et offre très peu de résistance."},
{d:4,th:"pof",q:"Lors d'un cisaillement de vent (windshear) avec perte soudaine de vent de face en approche, que se passe-t-il ?",a:"La vitesse indiquée chute brutalement et l'avion s'enfonce sous la trajectoire",w:["L'avion accélère","L'avion monte","Rien ne change"],e:"La réponse standard : pleine poussée, assiette élevée en respectant l'alarme de décrochage, sans rentrer les volets ni le train. C'est le chapitre « Windshear » du manuel 081."},

// =================== AJOUTS CHAPITRE PAR CHAPITRE (manuels Oxford de Badis) ===================
// --- 050 Météorologie
{d:1,th:"met",src:"050, ch. 1 : l'atmosphère",q:"Quel gaz est le plus abondant dans l'atmosphère ?",a:"L'azote (environ 78 %)",w:["L'oxygène (environ 78 %)","Le dioxyde de carbone (environ 21 %)","L'argon (environ 50 %)"],e:"Azote ≈ 78 %, oxygène ≈ 21 %, le reste (argon, CO₂, vapeur d'eau…) ≈ 1 %. La vapeur d'eau est rare en volume, mais c'est elle qui fait la météo."},
{d:2,th:"met",src:"050, ch. 2 : la pression",q:"Quelle est la différence entre QNH et QFF ?",a:"Les deux ramènent la pression au niveau de la mer, mais le QFF utilise la température réelle alors que le QNH utilise l'atmosphère standard",w:["Le QFF est la pression à l'aéroport","Le QNH est utilisé uniquement en croisière","C'est la même chose"],e:"Les météorologues utilisent le QFF pour tracer les cartes de pression ; les pilotes utilisent le QNH pour lire leur altitude."},
{d:2,th:"met",src:"050, ch. 3 : la densité",q:"Un air chaud et humide est-il plus ou moins dense qu'un air froid et sec, à pression égale ?",a:"Moins dense",w:["Plus dense","Exactement aussi dense","Ça dépend uniquement de l'altitude"],e:"La chaleur dilate l'air, et la vapeur d'eau est plus légère que l'air sec. Un air moins dense dégrade les performances : décollage plus long, montée plus lente."},
{d:2,th:"met",src:"050, ch. 4 : les systèmes de pression",q:"Quel temps est typique sous un anticyclone ?",a:"Un temps stable : peu de nuages, vents faibles, mais parfois brouillard ou brume le matin",w:["Des orages violents","Des vents très forts","De la pluie continue"],e:"L'air y descend et se réchauffe, ce qui dissipe les nuages. Le piège : en hiver, brouillard et stratus bas peuvent persister sous l'anticyclone."},
{d:3,th:"met",src:"050, ch. 4 : les systèmes de pression",q:"Qu'est-ce qu'un col en météorologie ?",a:"Une zone de pression neutre entre deux anticyclones et deux dépressions",w:["Un passage entre deux montagnes","Une dépression très creuse","Un front stationnaire"],e:"Les vents y sont faibles et variables ; on peut y trouver du brouillard en hiver et des orages en été."},
{d:2,th:"met",src:"050, ch. 5 : la température",q:"Qu'est-ce qu'une inversion de température ?",a:"Une couche où la température augmente avec l'altitude au lieu de diminuer",w:["Une baisse brutale de pression","Un vent qui change de sens","Une température négative au sol"],e:"L'inversion bloque les mouvements verticaux : elle piège la pollution, la brume et le brouillard en dessous. Une couche où la température reste constante s'appelle une isotherme."},
{d:3,th:"met",src:"050, ch. 6 : l'humidité",q:"Qu'appelle-t-on la sublimation ?",a:"Le passage direct de l'état solide à l'état gazeux (ou l'inverse), sans passer par le liquide",w:["Le passage du liquide au gaz","Le passage du gaz au liquide","La congélation de l'eau"],e:"La gelée blanche sur un avion se forme ainsi : la vapeur d'eau se dépose directement en glace sur une surface très froide."},
{d:4,th:"met",src:"050, ch. 7 : adiabatisme et stabilité",q:"Quand parle-t-on d'instabilité conditionnelle ?",a:"Quand le gradient réel de l'air se situe entre le gradient adiabatique saturé et le gradient adiabatique sec",w:["Quand l'air est toujours instable","Quand il y a une inversion","Quand l'air est totalement sec"],e:"L'air est stable s'il reste sec, mais devient instable s'il se sature en montant : la « condition », c'est la saturation. C'est souvent le cas dans la réalité."},
{d:3,th:"met",src:"050, ch. 8 : la turbulence",q:"Quels nuages signalent souvent des ondes de montagne ?",a:"Des nuages lenticulaires, en forme de lentille, immobiles au-dessus ou sous le vent des reliefs",w:["Des cumulonimbus","Des cirrus en filaments","Des stratus au sol"],e:"Sous ces ondes, des nuages « rotors » peuvent indiquer une turbulence très sévère. Le manuel 050 conseille de passer bien au-dessus du relief ou de l'éviter."},
{d:2,th:"met",src:"050, ch. 9 : l'altimétrie",q:"Par un air beaucoup plus froid que l'atmosphère standard, l'altimètre :",a:"Indique plus haut que la réalité : l'avion est plus bas qu'il ne le croit",w:["Indique plus bas que la réalité","Reste parfaitement juste","Se bloque"],e:"L'air froid est plus dense et « tassé ». C'est pour ça qu'on applique des corrections de température aux altitudes minimales par grand froid."},
{d:3,th:"met",src:"050, ch. 10 : les vents",q:"Qu'est-ce que le vent géostrophique ?",a:"Un vent théorique qui souffle parallèlement aux isobares, quand la force de pression équilibre la force de Coriolis",w:["Le vent mesuré au sol","Un vent qui va directement des hautes vers les basses pressions","Un vent de montagne"],e:"Plus les isobares sont serrées, plus il est fort. Près du sol, le frottement le ralentit et le fait tourner vers les basses pressions."},
{d:4,th:"met",src:"050, ch. 10 : les vents",q:"Dans l'hémisphère Nord, en descendant de 2 000 ft vers le sol, comment évolue généralement le vent ?",a:"Il faiblit et tourne vers la gauche (il « recule »)",w:["Il se renforce et tourne vers la droite","Il garde la même direction et la même force","Il s'inverse complètement"],e:"Le frottement du sol réduit la vitesse, donc la force de Coriolis : le vent dévie vers les basses pressions. Utile pour anticiper le vent à l'atterrissage."},
{d:3,th:"met",src:"050, ch. 11 : les vents en altitude",q:"Qu'est-ce que la turbulence en air clair (CAT) ?",a:"Une turbulence sans nuage visible, souvent près des courants-jets",w:["Une turbulence dans les cumulonimbus","Le souffle d'un avion devant soi","Une turbulence au ras du sol"],e:"Invisible à l'œil et au radar météo : d'où l'intérêt des prévisions et des comptes rendus des autres pilotes."},
{d:2,th:"met",src:"050, ch. 12 : les nuages",q:"Selon le manuel Oxford, comment définit-on le plafond (cloud ceiling) ?",a:"La hauteur au-dessus de l'aérodrome de la couche nuageuse la plus basse couvrant plus de 4 octas du ciel",w:["La hauteur du nuage le plus haut","La hauteur du premier nuage, même isolé","L'altitude maximale de l'avion"],e:"En pratique : la première couche BKN ou OVC. C'est elle qui compte pour les minima d'atterrissage."},
{d:3,th:"met",src:"050, ch. 13 : formation des nuages et précipitations",q:"Que décrit la théorie de Bergeron ?",a:"Dans un nuage mixte, les cristaux de glace grossissent aux dépens des gouttelettes surfondues, jusqu'à tomber",w:["La formation des éclairs","La formation du brouillard","Le déplacement des fronts"],e:"C'est le principal mécanisme de pluie aux latitudes moyennes. Dans les nuages chauds tropicaux, c'est plutôt la coalescence (des gouttes qui se rencontrent)."},
{d:2,th:"met",src:"050, ch. 13 : formation des nuages et précipitations",q:"Qu'est-ce qu'un nuage orographique ?",a:"Un nuage formé quand l'air est forcé de monter le long d'un relief",w:["Un nuage formé au-dessus de la mer","Un nuage de fumée","Un nuage qui descend d'une montagne"],e:"L'air soulevé se refroidit et se condense. Ces nuages peuvent cacher le relief : danger majeur en vol à vue."},
{d:2,th:"met",src:"050, ch. 14 : les orages",q:"De quoi un orage a-t-il besoin pour se former ?",a:"Un air instable, beaucoup d'humidité et un élément déclencheur qui soulève l'air",w:["Uniquement d'un air froid","D'un anticyclone","D'une inversion de température"],e:"Le déclencheur peut être le réchauffement du sol, un relief, un front froid ou une convergence."},
{d:4,th:"met",src:"050, ch. 14 : les orages",q:"Selon le manuel 050, à quelle distance minimale faut-il éviter un orage au radar au-dessus de 20 000 ft ?",a:"20 NM",w:["5 NM","10 NM","50 NM"],e:"En dessous de 20 000 ft : 10 NM minimum. La turbulence et la grêle peuvent s'étendre bien au-delà du nuage visible."},
{d:2,th:"met",src:"050, ch. 15 : la visibilité",q:"Quelles conditions favorisent le brouillard de rayonnement ?",a:"Une nuit claire, un vent faible et un air humide",w:["Un vent fort et un ciel couvert","Un après-midi chaud et ensoleillé","Un air très sec"],e:"Le sol se refroidit fortement par ciel clair et refroidit l'air au contact. Il se dissipe généralement dans la matinée avec le soleil."},
{d:3,th:"met",src:"050, ch. 15 : la visibilité",q:"Comment se forme le brouillard d'advection ?",a:"Quand un air chaud et humide se déplace au-dessus d'une surface plus froide (mer froide, sol froid)",w:["Par un refroidissement nocturne sans vent","Par la fumée des usines","Par une montée d'air le long d'une montagne"],e:"Contrairement au brouillard de rayonnement, il peut se former de jour, avec du vent, et persister longtemps (côtes en été, par exemple)."},
{d:3,th:"met",src:"050, ch. 15 : la visibilité",q:"Que mesure la RVR ?",a:"La portée visuelle de piste : la distance à laquelle le pilote peut voir les marques ou les feux de piste",w:["La visibilité générale autour de l'aéroport","La hauteur des nuages","La vitesse du vent sur la piste"],e:"RVR = Runway Visual Range, mesurée par des instruments le long de la piste. Elle décide si un atterrissage par mauvaise visibilité est autorisé."},
{d:3,th:"met",src:"050, ch. 16 : le givrage",q:"Selon le manuel 050, dans quelle plage de température le givrage du carburateur est-il le plus dangereux ?",a:"Entre −10 °C et +25 °C",w:["Uniquement en dessous de −20 °C","Uniquement au-dessus de +30 °C","Seulement à 0 °C exactement"],e:"La détente de l'air et l'évaporation du carburant refroidissent fortement le carburateur : il peut givrer même par une journée douce et humide."},
{d:2,th:"met",src:"050, ch. 16 : le givrage",q:"Qu'est-ce qu'une gouttelette surfondue ?",a:"Une goutte d'eau restée liquide en dessous de 0 °C, qui gèle au premier contact",w:["Un grêlon","Une goutte d'eau chaude","Un flocon de neige fondu"],e:"Ce sont elles qui provoquent le givrage des avions : elles gèlent instantanément en touchant l'aile."},
{d:3,th:"met",src:"050, ch. 17 : masses d'air et fronts",q:"Quel temps accompagne typiquement le passage d'un front froid actif ?",a:"Des averses, souvent orageuses, une saute de vent et une baisse de température",w:["Une pluie fine continue pendant des heures","Un ciel parfaitement clair","Un brouillard épais"],e:"L'air froid pousse l'air chaud vers le haut brutalement : cumulonimbus sur une bande étroite. Après le passage : bonne visibilité et averses."},
{d:4,th:"met",src:"050, ch. 19 : autres dépressions",q:"Comment appelle-t-on un cyclone tropical dans le Pacifique Nord-Ouest ?",a:"Un typhon",w:["Un ouragan","Une tornade","Une mousson"],e:"Ouragan (hurricane) dans l'Atlantique et le Pacifique Nord-Est, typhon dans le Pacifique Nord-Ouest, cyclone dans l'océan Indien. C'est le même phénomène."},
{d:3,th:"met",src:"050, ch. 20 : climatologie générale",q:"Qu'est-ce que la mousson ?",a:"Un renversement saisonnier des vents, qui apporte une saison très pluvieuse",w:["Une tempête de sable","Un vent froid d'hiver en Europe","Une marée exceptionnelle"],e:"En été, le continent se réchauffe plus que l'océan et attire l'air humide marin : pluies massives en Inde ou en Afrique de l'Ouest."},
{d:3,th:"met",src:"050, ch. 21 : vents locaux",q:"Qu'est-ce que le mistral ?",a:"Un vent froid et fort du nord qui descend la vallée du Rhône vers la Méditerranée",w:["Un vent chaud du Sahara","Une brise de mer","Un vent de montagne en Suisse"],e:"Il est accéléré par le resserrement de la vallée entre les Alpes et le Massif central. Il peut créer de la turbulence importante à Marseille."},
{d:3,th:"met",src:"050, ch. 21 : vents locaux",q:"Qu'est-ce que l'harmattan ?",a:"Un vent sec et chargé de poussière, qui souffle du Sahara vers l'Afrique de l'Ouest en hiver",w:["Un vent humide de mousson","Un vent froid des Alpes","Un courant-jet"],e:"Il peut réduire fortement la visibilité sur des centaines de kilomètres pendant plusieurs jours."},
{d:3,th:"met",src:"050, ch. 24 : observations par satellite",q:"Que montre une image satellite infrarouge ?",a:"La température des surfaces et des sommets de nuages, donc aussi de nuit",w:["Uniquement ce que l'œil verrait de jour","La vitesse du vent","La pression au sol"],e:"Les sommets les plus froids, donc les plus hauts, apparaissent en blanc vif : c'est ainsi qu'on repère les gros cumulonimbus."},
{d:2,th:"met",src:"050, ch. 25 : METAR",q:"Dans un METAR, que signifie « 26012G25KT » ?",a:"Vent du 260° à 12 nœuds, avec des rafales à 25 nœuds",w:["Visibilité de 2 600 m","Vent de 120° à 26 nœuds","Température de 26 °C"],e:"La direction est donnée par rapport au nord vrai, en dizaines de degrés. G = gust (rafale)."},
{d:3,th:"met",src:"050, ch. 25 : METAR",q:"Que signifie « +TSRA » dans un METAR ?",a:"Un orage avec forte pluie",w:["Une température en hausse","Une faible pluie verglaçante","Un ciel dégagé"],e:"+ = fort, − = faible. TS = thunderstorm (orage), RA = rain (pluie), SN = neige, FZ = verglaçant (freezing)."},
{d:4,th:"met",src:"050, ch. 25 : METAR",q:"Que signifie « NOSIG » à la fin d'un METAR ?",a:"Aucun changement significatif prévu dans les deux prochaines heures",w:["Pas de signal radio","Pas de nuages","Pas d'information disponible"],e:"C'est une prévision « tendance » (TREND) ajoutée au METAR, valable 2 heures."},
{d:3,th:"met",src:"050, ch. 26 : TAF",q:"Dans un TAF, que signifie le groupe « FM1200 » ?",a:"À partir de 12 h 00 UTC, les conditions changent rapidement et complètement pour celles indiquées",w:["Fréquence météo 120,0 MHz","Fin du message à 12 h","Brouillard à 1 200 m"],e:"FM (from) : changement rapide et complet. BECMG : changement progressif. TEMPO : fluctuations temporaires."},
{d:4,th:"met",src:"050, ch. 27 : cartes du temps significatif",q:"Sur une carte du temps significatif, que signifie « OCNL CB » ?",a:"Des cumulonimbus occasionnels, bien séparés les uns des autres",w:["Des cumulonimbus en ligne continue","Aucun cumulonimbus","Des cumulonimbus cachés dans d'autres nuages"],e:"ISOL = isolés, OCNL = occasionnels (bien séparés), FRQ = fréquents (peu ou pas d'espace entre eux), EMBD = noyés dans d'autres nuages (les plus dangereux)."},
{d:2,th:"met",src:"050, ch. 29 : information météo en vol",q:"Qu'est-ce que l'ATIS ?",a:"Un message enregistré diffusé en boucle à la radio avec la météo et les informations de l'aéroport",w:["Un radar anticollision","Un service de dépannage","Le plan de vol informatisé"],e:"Chaque version porte une lettre (« information Bravo ») ; le pilote l'annonce au contrôleur pour montrer qu'il a la dernière. Le VOLMET, lui, diffuse la météo de plusieurs aéroports."},

// --- 010 Droit aérien
{d:2,th:"law",src:"010, ch. 3 : navigabilité",q:"Qui délivre le certificat de navigabilité d'un avion ?",a:"L'État d'immatriculation de l'avion",w:["Le constructeur","La compagnie aérienne","L'aéroport de départ"],e:"Il atteste que l'avion est conforme à son type certifié et en état de voler. Il doit se trouver à bord."},
{d:2,th:"law",src:"010, ch. 4 : nationalité et immatriculation",q:"Quel préfixe d'immatriculation portent les avions français ?",a:"F (par exemple F-HTVA)",w:["FR","FA","N"],e:"N = États-Unis, G = Royaume-Uni, D = Allemagne, TS = Tunisie. Les combinaisons qui pourraient être confondues avec des signaux de détresse (SOS, PAN, XXX…) sont interdites."},
{d:2,th:"law",src:"010, ch. 5 : licences",q:"Quelle classe de certificat médical faut-il pour un pilote de ligne ?",a:"La classe 1",w:["La classe 2","La classe 3","Aucune"],e:"Classe 1 : pilotes professionnels (CPL, ATPL). Classe 2 : pilotes privés. Classe 3 : contrôleurs aériens."},
{d:1,th:"law",src:"010, ch. 6 : règles de l'air",q:"Deux avions arrivent face à face au même niveau. Que doivent-ils faire ?",a:"Tous les deux virer à droite",w:["Tous les deux virer à gauche","Le plus gros garde son cap","Le plus rapide monte"],e:"C'est la règle de base de l'air. Elle ressemble à la conduite à droite en voiture."},
{d:2,th:"law",src:"010, ch. 6 : règles de l'air",q:"Deux avions convergent au même niveau. Lequel doit céder le passage ?",a:"Celui qui voit l'autre sur sa droite",w:["Celui qui voit l'autre sur sa gauche","Le plus lent","Le plus haut"],e:"Comme la priorité à droite. Un avion qui en dépasse un autre doit, lui, le dépasser par la droite."},
{d:1,th:"law",src:"010, ch. 6 : règles de l'air",q:"De quelle couleur est le feu de navigation sur l'aile gauche d'un avion ?",a:"Rouge",w:["Vert","Blanc","Bleu"],e:"Rouge à gauche, vert à droite, blanc à l'arrière. La nuit, ça permet de savoir dans quel sens va un avion qu'on voit."},
{d:2,th:"law",src:"010, ch. 7 : procédures de départ",q:"Qu'est-ce qu'une SID ?",a:"Une procédure standard de départ aux instruments, qui guide l'avion de la piste vers la route",w:["Un code de sécurité","Une piste de secours","Un signal de détresse"],e:"SID = Standard Instrument Departure. À l'arrivée, l'équivalent est la STAR (Standard Arrival Route)."},
{d:3,th:"law",src:"010, ch. 8 : procédures d'approche",q:"Quelle est la différence entre une hauteur de décision (DH) et une hauteur minimale de descente (MDH) ?",a:"La DH s'utilise en approche de précision (avec guidage vertical), la MDH en approche classique sans guidage vertical",w:["C'est la même chose","La DH concerne le décollage","La MDH concerne seulement les hélicoptères"],e:"À la DH, si le pilote ne voit pas la piste, il remet les gaz. À la MDH, il peut rester en palier jusqu'au point de remise de gaz, sans descendre plus bas."},
{d:3,th:"law",src:"010, ch. 9 : approche indirecte",q:"Qu'est-ce qu'une approche indirecte (circling) ?",a:"Une approche aux instruments suivie d'un tour à vue de l'aéroport pour atterrir sur une autre piste",w:["Un circuit d'attente","Une approche automatique","Un atterrissage sans visibilité"],e:"Utilisée quand la piste en service n'a pas d'approche aux instruments. Manœuvre exigeante, près du sol, avec des minima plus élevés."},
{d:3,th:"law",src:"010, ch. 10 : circuits d'attente",q:"Quelles sont les trois façons standard d'entrer dans un circuit d'attente ?",a:"Directe, parallèle et décalée (en « goutte d'eau »)",w:["Rapide, lente et normale","Gauche, droite et centrale","Haute, basse et moyenne"],e:"Le choix dépend de la direction d'arrivée par rapport à l'axe du circuit, selon des secteurs définis par l'OACI."},
{d:3,th:"law",src:"010, ch. 13 : SSR et ACAS",q:"Que transmet le mode C d'un transpondeur ?",a:"L'altitude-pression de l'avion",w:["Le nom de la compagnie","La position GPS","La vitesse"],e:"Mode A = code d'identification (squawk), mode C = altitude, mode S = sélectif, avec des données supplémentaires (indicatif, vitesse, cap…)."},
{d:2,th:"law",src:"010, ch. 14 : espaces aériens",q:"Qu'est-ce qu'une CTR ?",a:"Une zone de contrôle autour d'un aéroport, du sol jusqu'à une certaine altitude",w:["Un couloir aérien en haute altitude","Une zone militaire interdite","Le centre de contrôle régional"],e:"Au-dessus, une TMA (région de contrôle terminale) gère les arrivées et départs ; les avions rejoignent ensuite les voies aériennes (airways)."},
{d:3,th:"law",src:"010, ch. 15 : services de la circulation aérienne",q:"Que signifient INCERFA, ALERFA et DETRESFA ?",a:"Les trois phases d'urgence du service d'alerte : incertitude, alerte, détresse",w:["Trois types de météo","Trois classes d'espace aérien","Trois catégories de pilotes"],e:"Exemple : un avion ne répond plus et n'arrive pas à l'heure prévue. L'alerte monte par phases jusqu'au déclenchement des secours."},
{d:4,th:"law",src:"010, ch. 16 : séparation",q:"Dans l'espace RVSM (entre FL 290 et FL 410), quelle séparation verticale minimale applique-t-on ?",a:"1 000 ft",w:["500 ft","2 000 ft","3 000 ft"],e:"Avant le RVSM, c'était 2 000 ft au-dessus de FL 290. Il faut des altimètres et un pilote automatique certifiés. Le VFR y est interdit."},
{d:3,th:"law",src:"010, ch. 18 : service d'information aéronautique",q:"Tous les combien de jours les informations aéronautiques importantes (cycle AIRAC) sont-elles mises à jour ?",a:"Tous les 28 jours",w:["Tous les 7 jours","Tous les 3 mois","Une fois par an"],e:"Les dates sont communes au monde entier, pour que les bases de données de navigation des avions soient toutes à jour en même temps."},
{d:2,th:"law",src:"010, ch. 19 : caractéristiques des aérodromes",q:"Que veut dire le numéro « 27 » peint sur une piste ?",a:"Que la piste est orientée environ au 270° magnétique (vers l'ouest)",w:["Que c'est la 27e piste de l'aéroport","Qu'elle mesure 2 700 m","Qu'elle est réservée aux avions de 27 tonnes"],e:"On arrondit le cap magnétique à la dizaine et on retire le zéro. L'autre bout de la même piste s'appelle 09. Avec deux pistes parallèles : 27L et 27R."},
{d:2,th:"law",src:"010, ch. 20 : aides visuelles",q:"Sur un PAPI (indicateur de pente d'approche), que signifient deux feux blancs et deux feux rouges ?",a:"L'avion est sur le bon plan de descente",w:["L'avion est trop haut","L'avion est trop bas","La piste est fermée"],e:"Quatre blancs : beaucoup trop haut. Quatre rouges : beaucoup trop bas. Moyen mnémotechnique en anglais : « white over white, you'll fly all night ; red over red, you're dead »."},
{d:3,th:"law",src:"010, ch. 24 : recherche et sauvetage",q:"Quelle est la fréquence radio internationale de détresse en aviation civile ?",a:"121,5 MHz",w:["118,0 MHz","243,0 MHz","406,0 MHz"],e:"243,0 MHz est son équivalent militaire. Les balises de détresse modernes (ELT) émettent sur 406 MHz vers les satellites, et aussi sur 121,5 MHz pour le guidage."},
{d:3,th:"law",src:"010, ch. 26 : enquêtes accidents",q:"Quel est le but d'une enquête sur un accident d'avion selon l'OACI (Annexe 13) ?",a:"Prévenir de futurs accidents, pas désigner des coupables",w:["Désigner le responsable et le punir","Calculer l'indemnisation des victimes","Décider si la compagnie peut continuer à voler"],e:"En France, c'est le BEA qui mène ces enquêtes. Les poursuites judiciaires, s'il y en a, sont une procédure séparée."},

// --- 081 Principes du vol
{d:2,th:"pof",src:"081, ch. 2 : l'atmosphère",q:"Que représente la pression dynamique q = ½ ρ V² ?",a:"La pression due au mouvement de l'air, mesurée par le tube de Pitot",w:["La pression de l'air immobile","La pression dans la cabine","La pression dans les réservoirs"],e:"Pression totale = pression statique + pression dynamique. La vitesse indiquée (IAS) est en fait une mesure de la pression dynamique."},
{d:2,th:"pof",src:"081, ch. 3 : théorie aérodynamique de base",q:"Que dit le théorème de Bernoulli pour un écoulement d'air ?",a:"Quand la vitesse de l'air augmente, sa pression statique diminue",w:["Quand la vitesse augmente, la pression augmente","La pression ne dépend pas de la vitesse","L'air ne peut pas accélérer"],e:"Au-dessus de l'aile, l'air va plus vite, donc la pression y est plus faible qu'en dessous : c'est une des façons d'expliquer la portance."},
{d:1,th:"pof",src:"081, ch. 4 : écoulement subsonique",q:"Qu'appelle-t-on la corde d'un profil d'aile ?",a:"La ligne droite qui relie le bord d'attaque au bord de fuite",w:["L'épaisseur maximale de l'aile","L'envergure","La courbure du dessus de l'aile"],e:"La courbure moyenne du profil s'appelle la cambrure. L'angle d'attaque se mesure entre la corde et le vent relatif."},
{d:3,th:"pof",src:"081, ch. 5 : la portance",q:"À quelle vitesse la finesse (rapport portance/traînée) est-elle maximale ?",a:"À la vitesse de traînée minimale (VMD)",w:["À la vitesse maximale","À la vitesse de décrochage","À vitesse nulle"],e:"C'est aussi la vitesse de meilleur plané : en panne de moteurs, c'est celle qui permet d'aller le plus loin."},
{d:3,th:"pof",src:"081, ch. 6 : la traînée",q:"Comment varie la traînée parasite avec la vitesse ?",a:"Elle augmente comme le carré de la vitesse",w:["Elle diminue avec la vitesse","Elle reste constante","Elle augmente comme le cube de la vitesse"],e:"Doubler la vitesse multiplie la traînée parasite par 4. La traînée induite, elle, diminue comme 1/V² : la somme donne la courbe en U de la traînée totale."},
{d:4,th:"pof",src:"081, ch. 6 : la traînée",q:"Pourquoi est-il délicat de voler en dessous de la vitesse de traînée minimale (« second régime ») ?",a:"Si la vitesse baisse, la traînée augmente, ce qui fait encore baisser la vitesse : l'avion est instable en vitesse",w:["Parce que les moteurs s'arrêtent","Parce que l'avion monte tout seul","Parce que l'avion devient plus léger"],e:"C'est l'instabilité en vitesse. En approche, l'automanette (autothrust) aide le pilote à tenir la vitesse."},
{d:2,th:"pof",src:"081, ch. 7 : le décrochage",q:"Pourquoi préfère-t-on qu'une aile décroche d'abord à son emplanture (près du fuselage) ?",a:"Pour que les ailerons, en bout d'aile, restent efficaces et que l'avion ne parte pas en roulis",w:["Pour décrocher plus vite","Pour réduire le bruit","Pour économiser du carburant"],e:"Les concepteurs vrillent l'aile (vrillage, washout) pour que le bout d'aile ait un angle d'attaque plus faible et décroche en dernier."},
{d:3,th:"pof",src:"081, ch. 7 : le décrochage",q:"Qu'est-ce qu'un « super décrochage » (deep stall) ?",a:"Un décrochage où le sillage de l'aile masque l'empennage en T, empêchant de baisser le nez",w:["Un décrochage à très haute altitude","Un décrochage pendant un virage","Un décrochage dû au givre"],e:"C'est un risque des avions à empennage en T. On les équipe souvent d'un « stick pusher » qui pousse le manche automatiquement avant le décrochage."},
{d:3,th:"pof",src:"081, ch. 8 : dispositifs hypersustentateurs",q:"Qu'est-ce qui caractérise un volet Fowler ?",a:"Il recule et s'abaisse, ce qui augmente à la fois la surface et la courbure de l'aile",w:["Il se replie au-dessus de l'aile","Il ne change que la couleur de l'aile","Il est placé sur le bord d'attaque"],e:"C'est le type de volet des avions de ligne : il donne beaucoup de portance supplémentaire, avec une traînée modérée au début de sa sortie."},
{d:2,th:"pof",src:"081, ch. 9 : contamination de la cellule",q:"Pourquoi même une fine couche de givre sur l'aile est-elle dangereuse au décollage ?",a:"Elle perturbe l'écoulement, réduit la portance maximale et augmente la vitesse de décrochage",w:["Elle alourdit seulement l'avion de quelques grammes","Elle n'a aucun effet","Elle améliore l'adhérence de l'air"],e:"Une rugosité comparable à du papier de verre peut réduire fortement la portance maximale. D'où le dégivrage obligatoire avant le décollage."},
{d:3,th:"pof",src:"081, ch. 10 : stabilité et contrôle",q:"Quelle est la différence entre stabilité statique et stabilité dynamique ?",a:"Statique : la tendance initiale à revenir à l'équilibre ; dynamique : la façon dont le mouvement évolue dans le temps (oscillations qui s'amortissent ou non)",w:["Statique = au sol, dynamique = en vol","Ce sont deux noms pour la même chose","Statique concerne le moteur, dynamique les ailes"],e:"Un avion peut être stable statiquement mais osciller de plus en plus : il est alors instable dynamiquement. Tu retrouves ici exactement les notions de l'automatique."},
{d:4,th:"pof",src:"081, ch. 10 : stabilité et contrôle",q:"Qu'est-ce que la marge statique ?",a:"La distance entre le centre de gravité et le point neutre : plus elle est grande, plus l'avion est stable en tangage",w:["La marge de carburant","La distance entre les deux ailes","La différence entre deux vitesses"],e:"Si le centre de gravité recule jusqu'au point neutre, la stabilité longitudinale disparaît."},
{d:3,th:"pof",src:"081, ch. 11 : les commandes",q:"Qu'est-ce que le lacet inverse (adverse yaw) ?",a:"Quand on braque les ailerons pour virer, le nez part d'abord du côté opposé au virage",w:["Le nez part dans le sens du virage","L'avion monte en virage","L'avion décroche en virage"],e:"L'aileron baissé crée plus de traînée. On le compense au palonnier ou avec des ailerons différentiels ou de type Frise."},
{d:3,th:"pof",src:"081, ch. 11 : les commandes",q:"À quoi sert l'équilibrage par masse (mass balance) d'une gouverne ?",a:"À éviter le flottement (flutter), une vibration qui peut détruire la gouverne",w:["À rendre la gouverne plus légère","À économiser du carburant","À faciliter le roulage"],e:"On place une masse devant l'axe de rotation de la gouverne pour que son centre de gravité soit sur l'axe ou devant."},
{d:3,th:"pof",src:"081, ch. 12 : mécanique du vol",q:"Le poids de l'avion change-t-il l'angle de plané (sans moteur) ?",a:"Non, il change seulement la vitesse de plané optimale",w:["Oui, un avion lourd plane beaucoup moins loin","Oui, un avion léger ne peut pas planer","Le poids n'a aucun effet sur rien"],e:"L'angle de plané dépend de la finesse. Plus lourd, l'avion plane à la même pente mais plus vite, donc il arrive plus tôt au sol."},
{d:4,th:"pof",src:"081, ch. 12 : mécanique du vol",q:"Que représente VMCA sur un bimoteur ?",a:"La vitesse minimale à laquelle on peut encore garder le contrôle en direction avec un moteur en panne",w:["La vitesse maximale en croisière","La vitesse de montée optimale","La vitesse de décrochage"],e:"En dessous, la gouverne de direction ne suffit plus pour contrer la dissymétrie de poussée. D'où l'importance de V1, VR et V2 au décollage."},
{d:3,th:"pof",src:"081, ch. 13 : vol à grande vitesse",q:"En montée à vitesse indiquée constante, comment évolue le nombre de Mach ?",a:"Il augmente",w:["Il diminue","Il reste constant","Il devient nul"],e:"La vitesse vraie augmente et la vitesse du son diminue avec la température : le Mach grimpe. C'est pour ça qu'on passe en Mach constant en haute altitude."},
{d:4,th:"pof",src:"081, ch. 14 : limitations",q:"Selon le manuel 081, quel est le facteur de charge limite positif d'un avion de ligne à réaction moderne ?",a:"2,5 g",w:["1,5 g","4,4 g","6 g"],e:"Il correspond à un virage d'environ 67° d'inclinaison en palier. Au-delà, la structure risque une déformation permanente. Le facteur limite négatif est de −1 g."},
{d:3,th:"pof",src:"081, ch. 14 : limitations",q:"Que montre le diagramme V-n (domaine de manœuvre) ?",a:"Les combinaisons de vitesse et de facteur de charge que l'avion peut supporter sans dommage",w:["La consommation selon la vitesse","Le bruit selon la vitesse","L'altitude selon le poids"],e:"À gauche, la limite est le décrochage ; en haut et en bas, la résistance de la structure ; à droite, la vitesse maximale de piqué VD."},
{d:3,th:"pof",src:"081, ch. 15 : cisaillement de vent",q:"Quels indices visuels peuvent annoncer un cisaillement de vent à l'approche ?",a:"Un orage proche, de la pluie forte qui tombe d'un nuage (virga), de la poussière soulevée au sol",w:["Un ciel parfaitement dégagé et calme","Un arc-en-ciel","Un brouillard léger"],e:"Le manuel 081 insiste : en cas de doute, il vaut mieux retarder l'approche ou se dérouter que de tenter l'atterrissage."},
{d:4,th:"pof",src:"081, ch. 16 : les hélices",q:"Pourquoi utilise-t-on un petit pas d'hélice au décollage et un grand pas en croisière ?",a:"Petit pas : l'hélice tourne vite et donne une forte traction à basse vitesse ; grand pas : elle « mord » plus d'air et reste efficace à grande vitesse",w:["Pour réduire le bruit uniquement","Pour économiser l'huile","C'est l'inverse"],e:"Comme les vitesses d'un vélo : petit braquet pour démarrer, grand braquet pour rouler vite. L'hélice à vitesse constante règle le pas automatiquement."},

// --- 040 Performances humaines (Book 8) ---
{d:1,th:"hp",src:"040, ch. 2 : circulation sanguine",q:"Pourquoi le monoxyde de carbone (CO) est-il si dangereux en cabine ?",a:"L'hémoglobine le fixe 210 à 250 fois plus facilement que l'oxygène, et il est inodore",w:["Il fait monter la pression dans les oreilles","Il remplace l'azote dans le sang","Il n'est dangereux qu'au-dessus de 30 000 ft"],e:"Le CO prend la place de l'oxygène sur l'hémoglobine (carboxyhémoglobine) : le sang transporte moins d'oxygène, comme une hypoxie. Source typique : une fuite du chauffage cabine autour de l'échappement sur un avion à pistons."},
{d:2,th:"hp",src:"040, ch. 2 : circulation sanguine",q:"Après un don du sang, combien de temps un pilote doit-il attendre avant de voler ?",a:"Au moins 24 heures",w:["2 heures","12 heures","7 jours"],e:"Le manuel recommande de boire, de rester allongé 15 à 20 min, et de ne pas voler pendant au moins 24 h, à cause du risque de malaise (syncope)."},
{d:1,th:"hp",src:"040, ch. 4 : oreille et équilibre",q:"Au décollage, une forte accélération donne l'impression de cabrer. Comment s'appelle cette illusion ?",a:"L'illusion somatogravique",w:["L'autocinèse","L'effet Coriolis","Le trou noir"],e:"Les otolithes (petits « cailloux » de l'oreille interne) ne distinguent pas une accélération d'une inclinaison de la tête vers l'arrière. De nuit, sans repère extérieur, le pilote croit monter et risque de pousser sur le manche vers le sol."},
{d:2,th:"hp",src:"040, ch. 4 : oreille et équilibre",q:"En virage stabilisé, le pilote tourne brusquement la tête et croit que le taux de virage change. Quel est ce phénomène ?",a:"L'effet Coriolis (stimulation croisée des canaux semi-circulaires)",w:["L'illusion somatogravique","La vision en tunnel","Le vertige alternobarique"],e:"Un mouvement de tête de plus de 3° par seconde environ pendant un virage stimule plusieurs canaux en même temps. Règle pratique : éviter les mouvements de tête brusques en virage, surtout en vol aux instruments."},
{d:1,th:"hp",src:"040, ch. 5 : l'œil",q:"Combien de temps faut-il à l'œil pour s'adapter complètement à l'obscurité ?",a:"Environ 30 minutes",w:["Environ 10 secondes","Environ 2 minutes","Environ 3 heures"],e:"À la lumière forte, l'œil s'adapte en une dizaine de secondes. À l'obscurité, il faut environ 30 min pour que les bâtonnets (rods) deviennent très sensibles. Un flash de lumière blanche détruit cette adaptation."},
{d:2,th:"hp",src:"040, ch. 5 : l'œil",q:"Pourquoi un avion en route de collision peut-il rester invisible jusqu'au dernier moment ?",a:"Il garde un relèvement constant et peut rester sur la tache aveugle de la rétine",w:["Parce que les cônes ne voient pas le blanc","Parce que l'œil ne voit pas en dessous de 1 000 ft","Parce qu'un avion en approche est toujours dans le soleil"],e:"Un avion en collision ne bouge pas dans le champ de vision : il ne déclenche pas l'attention et peut tomber sur la tache aveugle (là où le nerf optique entre dans l'œil). D'où le balayage visuel avec des mouvements d'yeux fréquents."},
{d:2,th:"hp",src:"040, ch. 5 : l'œil",q:"Le centre de la rétine (fovéa) contient uniquement…",a:"des cônes : vision nette et des couleurs, mais peu sensible la nuit",w:["des bâtonnets : vision de nuit","autant de cônes que de bâtonnets","aucune cellule sensible : c'est la tache aveugle"],e:"Les cônes (couleurs, détails) sont au centre ; les bâtonnets (sensibles à la faible lumière) sont en périphérie. La nuit, on voit mieux un objet en regardant légèrement à côté."},
{d:1,th:"hp",src:"040, ch. 6 : santé et hygiène",q:"À quel rythme le corps élimine-t-il l'alcool, environ ?",a:"Une unité d'alcool par heure",w:["Une unité toutes les 10 minutes","Trois unités par heure","Tout est éliminé après une nuit de sommeil, quelle que soit la quantité"],e:"On ne peut pas accélérer l'élimination (café, douche…). Plus on a bu, plus le délai avant de voler est long : la règle des 8 h minimum n'est qu'un plancher."},
{d:2,th:"hp",src:"040, ch. 8 : traitement de l'information",q:"Combien d'éléments sans lien la mémoire à court terme peut-elle retenir ?",a:"Environ 7 ± 2",w:["Environ 2 ± 1","Environ 15 ± 5","Il n'y a pas de limite"],e:"Au-delà, des éléments se perdent ou s'inversent. C'est pour ça qu'on écrit une clairance de départ compliquée au lieu de la mémoriser, et que la mémoire à court terme est très sensible aux interruptions."},
{d:3,th:"hp",src:"040, ch. 10 : illusions visuelles",q:"En approche vers une piste qui monte (pente positive), quel est le risque ?",a:"Faire une approche trop basse, car la piste paraît plus courte et plus proche",w:["Faire une approche trop haute","Atterrir trop vite","Aucun : la pente ne change pas l'image de la piste"],e:"La piste montante semble plus proche : le pilote croit être trop haut et descend. Risque de toucher avant la piste. Une piste descendante donne l'effet inverse : approche trop haute."},
{d:2,th:"hp",src:"040, ch. 10 : illusions visuelles",q:"La nuit, une étoile isolée semble bouger et le pilote la prend pour un avion. Comment s'appelle cette illusion ?",a:"L'autocinèse",w:["L'illusion somatogravique","La myopie du champ vide","Le flicker vertigo"],e:"En fixant une lumière isolée sans autre repère, les petits mouvements de l'œil sont interprétés comme un mouvement de la lumière. Remède : déplacer le regard, ne pas fixer."},
{d:2,th:"hp",src:"040, ch. 11 : sommeil et décalage horaire",q:"Pourquoi le décalage horaire (jet lag) est-il plus dur vers l'est que vers l'ouest ?",a:"L'horloge interne tourne naturellement sur environ 25 h : elle s'allonge plus facilement qu'elle ne raccourcit",w:["Parce qu'on vole plus haut vers l'est","Parce que les vols vers l'est sont plus longs","Ce n'est pas vrai : c'est pareil dans les deux sens"],e:"New York → Londres : la journée ne dure que 19 h alors que le corps « voudrait » 25 h. Vers l'ouest, la journée s'allonge, ce qui va dans le sens de l'horloge interne."},
{d:3,th:"hp",src:"040, ch. 13 : comportement et attitudes",q:"Laquelle de ces attitudes fait partie des cinq attitudes dangereuses identifiées en aviation ?",a:"L'invulnérabilité : « Ça ne peut pas m'arriver »",w:["La prudence : « Je vérifie deux fois »","L'assertivité : « Je dis ce que je vois »","La synergie : « On décide ensemble »"],e:"Les cinq attitudes dangereuses : anti-autorité, impulsivité, invulnérabilité, macho (« Je vais leur montrer »), résignation (« Tant pis, je n'y peux rien »)."},
{d:3,th:"hp",src:"040, ch. 15 : prise de décision",q:"Que veut dire la méthode de décision DODAR utilisée par British Airways ?",a:"Diagnose, Options, Decide, Assign, Review (diagnostic, options, décision, répartition des tâches, revue)",w:["Descend, Overfly, Divert, Approach, Return","Detect, Observe, Delay, Act, Report","Data, Order, Direction, Altitude, Radio"],e:"C'est un fil conducteur pour décider en équipe sous pression : on comprend le problème, on liste les options, on choisit, on répartit le travail, puis on vérifie que ça marche."},
// --- 033 Préparation du vol (Book 7) ---
{d:2,th:"fp",src:"033, ch. 2 : politique carburant",q:"Quelle est la réserve finale (final reserve) pour un avion à réaction ?",a:"30 minutes d'attente à 1 500 ft au-dessus de l'aérodrome",w:["45 minutes de croisière","10 % du carburant d'étape","2 heures de vol"],e:"Pour un moteur à pistons, c'est 45 min. Cette réserve ne doit pas être entamée en vol normal : si on prévoit d'y toucher, on déclare une urgence carburant."},
{d:3,th:"fp",src:"033, ch. 2 : politique carburant",q:"Comment calcule-t-on le carburant de route supplémentaire (contingency fuel), en règle de base ?",a:"Le plus grand entre 5 % du carburant d'étape et 5 minutes d'attente à 1 500 ft",w:["Toujours 10 % du carburant total","Le plus petit entre 3 % et 10 minutes","Une valeur fixe de 500 kg"],e:"Il couvre les imprévus (vent plus fort, niveau différent). Avec un dégagement en route disponible, on peut descendre à 3 % du carburant d'étape."},
{d:3,th:"fp",src:"033, ch. 2 : politique carburant",q:"Vers un aérodrome isolé (sans dégagement possible), quelle réserve prévoit-on pour un avion à turbine ?",a:"2 heures de croisière normale au-dessus de la destination, réserve finale comprise",w:["30 minutes d'attente seulement","Rien de plus : on ne peut pas dégager","5 % du carburant d'étape"],e:"Comme il n'y a pas d'aérodrome de dégagement, il faut de quoi attendre que la situation s'améliore. Pour un avion à pistons : 45 min + 15 % du temps de vol, ou 2 h (le plus petit)."},
{d:2,th:"fp",src:"033, ch. 13 : point de non-retour (PSR)",q:"Qu'est-ce que le point de non-retour (PSR, ex-PNR) ?",a:"Le point le plus éloigné d'où l'avion peut encore revenir au départ sans entamer ses réserves obligatoires",w:["Le point à mi-distance entre départ et destination","Le point où il faut le même temps pour continuer ou faire demi-tour","Le point où les réservoirs sont vides"],e:"Il se calcule avec l'autonomie de sécurité (safe endurance), pas l'autonomie totale. À ne pas confondre avec le point d'égal temps (PET), où continuer ou revenir prend le même temps."},
{d:2,th:"fp",src:"033, ch. 12 : point d'égal temps (PET)",q:"Qu'est-ce que le point d'égal temps (PET) ?",a:"Le point de la route où il faut autant de temps pour continuer vers la destination que pour revenir",w:["Le point le plus éloigné d'où on peut revenir","Le milieu exact de la route en distance","Le point où l'avion atteint son niveau de croisière"],e:"Avec du vent, le PET n'est pas au milieu : il se déplace vers le côté d'où vient le vent. Il sert à décider vite en cas de panne moteur ou de passager malade."},
{d:1,th:"fp",src:"033, ch. 9 : cartes de radionavigation",q:"Quelle projection utilisent la plupart des cartes de radionavigation en route (Jeppesen, AERAD) ?",a:"La projection conique conforme de Lambert",w:["La projection de Mercator directe","La projection stéréographique polaire","Aucune projection : ce sont des photos"],e:"Elle conserve les angles (conforme) et une ligne droite y est presque une orthodromie (route la plus courte). Les cartes Jeppesen sont des sources secondaires : l'autorité, c'est l'AIP de l'État."},
{d:2,th:"fp",src:"033, ch. 11 : plan de vol ATC",q:"Un vol couvert par un plan de vol répétitif (RPL) prévoit 30 minutes de retard ou plus. Que doit faire l'exploitant ?",a:"Prévenir immédiatement l'organisme ATS de l'aérodrome de départ",w:["Rien, le RPL reste valable toute la journée","Refaire un nouveau RPL pour toute la saison","Prévenir l'aérodrome d'arrivée seulement"],e:"À cause de la régulation du trafic (flow control), ne pas prévenir peut faire annuler automatiquement le RPL pour ce vol."},
{d:3,th:"fp",src:"033, ch. 7 : ETOPS",q:"Que signifie une approbation ETOPS 120 minutes pour un biréacteur ?",a:"L'avion ne doit jamais être à plus de 120 minutes (à vitesse monomoteur) d'un aérodrome adéquat",w:["L'avion peut voler 120 minutes avec un seul moteur au décollage","Le vol ne doit pas durer plus de 120 minutes","L'équipage doit se relayer toutes les 120 minutes"],e:"ETOPS : vols long-courriers avec deux moteurs. Si un moteur tombe en panne au pire endroit, l'avion doit pouvoir rejoindre un aérodrome dans le temps approuvé (60, 120, 180 min…)."},
// --- 010 Droit aérien (Book 1, 2014) ---
{d:1,th:"law",src:"010, ch. 2 : conventions internationales",q:"Quelle convention, signée en 1944, a créé l'OACI (ICAO) ?",a:"La convention de Chicago",w:["La convention de Tokyo","La convention de Montréal","La convention de Varsovie"],e:"La convention de Chicago (1944) fixe les règles de l'aviation civile internationale et crée l'OACI, qui publie les annexes (Annexe 1 licences, Annexe 2 règles de l'air, etc.)."},
{d:2,th:"law",src:"010, ch. 2 : conventions internationales",q:"Que donne la première liberté de l'air ?",a:"Le droit de survoler le territoire d'un autre État sans y atterrir",w:["Le droit d'atterrir pour faire le plein","Le droit d'embarquer des passagers dans un autre État","Le droit de faire des vols intérieurs à l'étranger"],e:"Les deux premières libertés sont « techniques » : 1re = survoler, 2e = atterrir pour une raison non commerciale (plein, panne). Les suivantes sont commerciales."},
{d:3,th:"law",src:"010, ch. 2 : conventions internationales",q:"Quelle convention de 1963 traite des infractions commises à bord d'un avion ?",a:"La convention de Tokyo",w:["La convention de Chicago","La convention de Montréal","La convention de Rome"],e:"Tokyo (1963) : l'État d'immatriculation est compétent pour les infractions à bord, et le commandant de bord a des pouvoirs (débarquer, retenir une personne). Montréal (1971) vise les actes illicites contre la sécurité de l'aviation."},
{d:2,th:"law",src:"010, ch. 5 : licences",q:"Jusqu'à quel âge un pilote peut-il exercer en transport aérien commercial ?",a:"Jusqu'à 65 ans",w:["Jusqu'à 55 ans","Jusqu'à 60 ans, sans exception","Il n'y a pas de limite d'âge"],e:"Une fois 65 ans atteints, il ne peut plus être pilote en transport commercial. Entre 60 et 64 ans, il doit voler en équipage avec un pilote de moins de 60 ans."},
{d:2,th:"law",src:"010, ch. 5 : licences",q:"Combien de temps reste valable une qualification de type (type rating) multimoteur ?",a:"12 mois",w:["6 mois","24 mois","Toute la carrière"],e:"Il faut la prolonger avec un contrôle de compétence. C'est l'une des raisons pour lesquelles les pilotes de ligne passent régulièrement au simulateur."},
{d:1,th:"law",src:"010, ch. 6 : règles de l'air",q:"Deux avions arrivent face à face avec un risque de collision. Que doivent-ils faire ?",a:"Chacun vire à droite",w:["Chacun vire à gauche","Le plus lourd garde son cap","Le plus haut monte, le plus bas descend"],e:"Aucun n'a la priorité : les deux s'écartent par la droite, comme les voitures qui se croisent dans la plupart des pays."},
{d:2,th:"law",src:"010, ch. 6 : règles de l'air",q:"Deux avions du même type convergent au même niveau. Lequel doit céder le passage ?",a:"Celui qui a l'autre sur sa droite",w:["Celui qui a l'autre sur sa gauche","Le plus rapide","Celui qui vole vers le nord"],e:"Celui qui cède doit passer derrière l'autre, pas dessus, dessous ni devant : il vire donc à droite."},
{d:2,th:"law",src:"010, ch. 6 : règles de l'air",q:"Au-dessus de l'altitude de transition, comment exprime-t-on la position verticale ?",a:"En niveaux de vol (calage 1013,25 hPa)",w:["En altitude au QNH","En hauteur au QFE","En pieds au-dessus de l'obstacle le plus haut"],e:"En dessous de l'altitude de transition : altitude au QNH. Au-dessus : niveaux de vol, tout le monde au même calage standard, ce qui évite les erreurs entre avions."},
{d:3,th:"law",src:"010, ch. 11 : panne radio",q:"Panne radio en IMC, en route sous contrôle radar : que fait le pilote ?",a:"Il affiche 7600 et garde le plan de vol actuel pendant 7 minutes, puis suit le plan de vol déposé",w:["Il affiche 7500 et descend immédiatement","Il affiche 7700 et fait demi-tour","Il garde son cap pendant 30 minutes, puis atterrit au plus proche"],e:"Codes transpondeur : 7500 = intervention illicite, 7600 = panne radio, 7700 = urgence. Hors zone radar, le délai est de 20 minutes après le point de compte rendu manqué."},
// --- 022 Électricité (Book 3) ---
{d:1,th:"sys",src:"022 Électricité, ch. 4 : batteries",q:"Quelle est la tension nominale d'un élément de batterie au plomb (en charge) ?",a:"2 volts",w:["1,2 volt","12 volts","28 volts"],e:"À vide, un élément affiche 2,2 V. Une batterie de 24 V contient donc 12 éléments en série. L'état de charge se vérifie avec un hydromètre (densité de l'électrolyte)."},
{d:2,th:"sys",src:"022 Électricité, ch. 4 : batteries",q:"Qu'est-ce que l'emballement thermique (thermal runaway) d'une batterie NiCd ?",a:"La chaleur baisse la résistance interne, le courant de charge augmente, ce qui chauffe encore plus, jusqu'à la destruction",w:["Une décharge trop lente par temps froid","La perte d'eau de l'électrolyte en altitude","Un court-circuit volontaire pour tester la batterie"],e:"C'est une boucle de rétroaction positive (comme en automatique : un système instable). Un capteur thermique coupe la charge à une température limite."},
{d:2,th:"sys",src:"022 Électricité, ch. 3 : protection des circuits",q:"Pourquoi un disjoncteur « trip-free » est-il plus sûr ?",a:"Il se déclenche sur défaut même si on maintient le bouton enfoncé",w:["Il ne se déclenche jamais","Il se réarme tout seul après 10 secondes","Il coupe tous les circuits de l'avion en même temps"],e:"Un disjoncteur « non trip-free » peut être maintenu enfoncé pendant un défaut : le circuit reste alimenté, ce qui est dangereux (surchauffe, feu)."},
{d:1,th:"sys",src:"022 Électricité, ch. 11 : courant alternatif",q:"Quelle est la fréquence standard du courant alternatif à bord d'un avion de ligne ?",a:"400 Hz",w:["50 Hz","60 Hz","1 000 Hz"],e:"Le standard est 115 V / 200 V / 400 Hz triphasé. À 400 Hz, les transformateurs et moteurs sont beaucoup plus petits et légers qu'à 50 Hz : en avion, chaque kilo compte."},
{d:2,th:"sys",src:"022 Électricité, ch. 14 : transformateurs",q:"À quoi sert un TRU (transformer rectifier unit) ?",a:"Transformer le 115 V alternatif en 28 V continu",w:["Transformer le 28 V continu en 115 V alternatif","Stocker l'énergie comme une batterie","Mesurer la fréquence du réseau"],e:"Le TRU combine un transformateur (baisse la tension) et un redresseur (alternatif → continu). L'inverse (continu → alternatif) est fait par un onduleur (inverter)."},
{d:2,th:"sys",src:"022 Électricité, ch. 9 : métallisation",q:"À quoi sert la métallisation (bonding) de la structure ?",a:"Relier électriquement toutes les pièces métalliques pour éviter les étincelles d'électricité statique",w:["Rendre l'avion invisible au radar","Alimenter les feux de navigation","Chauffer les bords d'attaque"],e:"Toutes les pièces sont au même potentiel : pas d'arc entre deux pièces, donc pas de risque d'incendie près du carburant. Elle sert aussi de chemin de retour du courant."},
{d:1,th:"sys",src:"022 Électricité, ch. 9 : métallisation",q:"À quoi servent les petites tiges (static wicks) au bord de fuite des ailes et des gouvernes ?",a:"Évacuer l'électricité statique accumulée sur la cellule",w:["Mesurer la vitesse","Réduire la traînée","Servir d'antenne radio principale"],e:"La statique se décharge dans l'air par effet de pointe. Sans elles, elle se déchargerait n'importe comment et brouillerait les radios."},
{d:3,th:"sys",src:"022 Électricité, ch. 17 : portes logiques",q:"Une porte NAND donne 0 en sortie seulement quand…",a:"toutes ses entrées sont à 1",w:["toutes ses entrées sont à 0","une seule entrée est à 1","les entrées sont différentes"],e:"NAND = NOT AND : on fait le ET, puis on inverse. Le ET donne 1 seulement si tout est à 1, donc le NAND donne 0 seulement dans ce cas."},
// =================== 090 COMMUNICATIONS ===================
{d:1,th:"com",q:"Comment épelle-t-on la lettre A dans l'alphabet aéronautique ?",a:"Alfa",w:["Alpha-one","Apple","Adam"],e:"Alfa, Bravo, Charlie, Delta, Echo, Foxtrot, Golf, Hotel, India, Juliett, Kilo, Lima, Mike, November, Oscar, Papa, Quebec, Romeo, Sierra, Tango, Uniform, Victor, Whiskey, X-ray, Yankee, Zulu."},
{d:1,th:"com",q:"Que signifie le message « MAYDAY MAYDAY MAYDAY » ?",a:"Une détresse : l'avion est en danger grave et a besoin d'aide immédiate",w:["Une simple demande d'information","Une urgence sans danger immédiat","Un message de fin de vol"],e:"Pour une urgence moins grave (passager malade, panne non critique), on utilise « PAN PAN » (trois fois)."},
{d:2,th:"com",q:"Que veut dire « WILCO » à la radio ?",a:"« J'ai compris et je vais exécuter » (will comply)",w:["« Je répète »","« Attendez »","« Négatif »"],e:"« ROGER » veut seulement dire « j'ai bien reçu ». Les autorisations importantes (cap, niveau, piste) doivent être collationnées, c'est-à-dire répétées."},
{d:2,th:"com",q:"Pourquoi le pilote doit-il collationner (readback) certaines instructions ?",a:"Pour que le contrôleur vérifie que le pilote a bien compris, et corrige une erreur avant qu'elle ne soit dangereuse",w:["Pour remplir le silence radio","Pour l'enregistrement uniquement","Par politesse"],e:"Une erreur de niveau ou de piste mal comprise est une cause classique d'incident. Le collationnement est une barrière de sécurité (modèle du fromage suisse)."},
{d:3,th:"com",q:"Comment prononce-t-on le chiffre 9 à la radio en anglais aéronautique ?",a:"« NINER »",w:["« NINE »","« NEUN »","« NOVEM »"],e:"Pour éviter la confusion avec l'allemand « nein » (non). De même, 3 se dit « TREE » et 5 « FIFE »."},
{d:4,th:"com",q:"Que demande un pilote quand il dit « request QDM » ?",a:"Le cap magnétique à suivre pour rejoindre la station sans vent",w:["La météo de destination","La pression au sol","L'heure exacte"],e:"QDM, QDR, QTE, QUJ… ces codes Q donnent des relèvements. Ils sont au programme de 090 et de radionavigation."}
];
registerBank("atpl", "Aviation ATPL", THEMES, QUESTIONS);
})();
